// Üretilen dosya: tool/ozgun/uret.py. Fizik · İş, enerji, güç ve momentum hesapları (orta).
const ozPhysics8Orta = <(String, String, List<String>, String)>[
  ('Bir cisme F = (3 î + 4 ĵ) N sabit kuvveti etki ederken cismin yer değiştirmesi d = (2 î + 1 ĵ) m oluyor. Kuvvetin yaptığı iş kaç joule\'dür?', '10 J', ['11 J', '2,5 J', '14 J'], 'İş, kuvvet ile yer değiştirmenin skaler çarpımıdır: W = 3·2 + 4·1 = 10 J.'),
  ('Bir vinç halatı, 500 kg\'lık bir yükü 2 m/s² ivmeyle yukarı hızlandırarak 4 m kaldırıyor. Halatın gerilme kuvvetinin yaptığı iş kaç kJ\'dür? (g = 10 m/s²)', '24 kJ', ['20 kJ', '4,8 kJ', '16 kJ'], 'Gerilme T = m(g + a) = 500·12 = 6000 N; iş W = 6000·4 = 24 000 J = 24 kJ.'),
  ('Kütlesi 5 kg olan bir blok, 10 m uzunluğundaki ve yatayla 30° açı yapan bir eğik düzlemin tepesinden dibine kayıyor. Bu sırada yer çekimi kuvvetinin blok üzerinde yaptığı iş kaç joule\'dür? (g = 10 m/s²)', '250 J', ['500 J', '433 J', '2500 J'], 'Çekim kuvvetinin işi yalnız düşey yükseklik farkına bağlıdır: h = 10·sin30° = 5 m, W = mgh = 5·10·5 = 250 J.'),
  ('Bir kutu, 5 N\'luk sabit kinetik sürtünmeli bir zeminde A noktasından 4 m uzaktaki B noktasına itiliyor, sonra yine itilerek A\'ya geri getiriliyor. Gidiş-dönüşte sürtünme kuvvetinin toplam işi kaç joule\'dür?', '−40 J', ['0 J', '−20 J', '40 J'], 'Sürtünme her iki yönde de harekete zıttır; toplam yol 8 m olduğundan W = −5·8 = −40 J. Yer değiştirme sıfır olsa da iş sıfır olmaz.'),
  ('Bir cisme etki eden kuvvet, cisim 4 m ilerlerken düzgün biçimde 0\'dan 20 N\'a artıyor ve kuvvet hep hareket yönünde kalıyor. Bu kuvvetin yaptığı iş kaç joule\'dür?', '40 J', ['80 J', '20 J', '160 J'], 'Kuvvet doğrusal arttığından ortalama kuvvet 10 N alınabilir: W = 10·4 = 40 J. Bu, kuvvet-konum doğrusunun altındaki üçgenin alanıdır.'),
  ('SI dışı bir birim olan erg ile joule arasındaki ilişki hangisidir?', '1 J = 10⁷ erg', ['1 J = 10³ erg', '1 J = 10⁵ erg', '1 erg = 10⁷ J'], 'Erg, CGS sisteminde 1 din kuvvetin 1 cm\'lik yer değiştirmede yaptığı iştir; 1 N = 10⁵ din ve 1 m = 10² cm olduğundan 1 J = 10⁷ erg olur.'),
  ('Bir cisme sürekli doğuya yönelik 10 N\'luk sabit kuvvet etki ederken cisim önce 3 m kuzeye, sonra 4 m doğuya gidiyor. Bu kuvvetin yaptığı toplam iş kaç joule\'dür?', '40 J', ['70 J', '50 J', '30 J'], 'Sabit kuvvetin işi yalnız kuvvet doğrultusundaki net yer değiştirmeye bağlıdır. Kuzeye gidişte iş sıfırdır, doğuya 4 m\'de 40 J iş yapılır.'),
  ('Kinetik sürtünme kuvvetinin yaptığı işin, korunumlu kuvvetlerin aksine izlenen yola bağlı olmasının nedeni hangisidir?', 'Kuvvet hep harekete zıt olduğundan negatif iş yolla birikir', ['Sürtünme kuvveti cismin kütlesine bağlı değildir', 'Sürtünme kuvveti yalnız yer değiştirmenin yönüne bağlıdır', 'Sürtünme kuvvetinin büyüklüğü hıza göre sürekli ve rastgele değişir'], 'Kinetik sürtünme her an hareket yönüne zıttır; yol uzadıkça negatif iş birikir. Bu nedenle uzun yoldan gidildiğinde daha fazla enerji ısıya dönüşür.'),
  ('Yay sabiti 300 N/m olan bir yay, denge konumundan itibaren 10 cm gerilmiş durumdan 20 cm gerilmiş duruma getiriliyor. Bu ek germe için yapılması gereken iş kaç joule\'dür?', '4,5 J', ['1,5 J', '6 J', '0,45 J'], 'İş, esneklik enerjisi farkıdır: ½k(x₂² − x₁²) = ½·300·(0,04 − 0,01) = 150·0,03 = 4,5 J.'),
  ('Gerilmiş bir yay serbest bırakılıp denge konumuna dönerken yay kuvvetinin, yaya bağlı cisim üzerinde yaptığı iş için hangisi doğrudur?', 'Pozitiftir, çünkü kuvvet hareket yönündedir', ['Negatiftir, çünkü kuvvet geri çağırıcıdır', 'Sıfırdır, çünkü yay kuvveti korunumludur', 'Önce pozitif sonra negatif olup toplamı sıfırdır'], 'Denge konumuna dönerken yay kuvveti cismi dengeye doğru çeker ve cisim de o yönde hareket eder; iş pozitiftir ve yayın enerjisi kinetik enerjiye dönüşür.'),
  ('Bir kaleci 6 m/s hızla gelen 2 kg\'lık sağlık topunu, ellerini geri çekerek 0,5 m\'lik bir mesafede durduruyor. Kalecinin topa uyguladığı ortalama kuvvet kaç newton\'dur?', '72 N', ['36 N', '24 N', '144 N'], 'Topun kinetik enerjisi ½·2·36 = 36 J\'dür. Bu enerji 0,5 m\'de sıfırlanır: F = 36 / 0,5 = 72 N.'),
  ('Kütlesi 20 g olan bir mermi 400 m/s hızla bir tahta bloğa girip 10 cm sonra duruyor. Tahtanın mermiye uyguladığı ortalama direnç kuvveti kaç newton\'dur?', '16 000 N', ['1600 N', '8000 N', '160 000 N'], 'Kinetik enerji ½·0,02·400² = 1600 J\'dür. Durdurucu iş bu enerjiye eşit: F = 1600 / 0,1 = 16 000 N.'),
  ('Bir cisme etki eden kuvvetlerin yaptığı net iş belli bir süre boyunca sıfır kalıyorsa bu süre için kesin olarak ne söylenebilir?', 'Cismin süratinin başta ve sonda aynı olduğu', ['Cismin hiç hareket etmediği', 'Cisme hiçbir kuvvet etki etmediği', 'Cismin hızının yönünün bu süre boyunca hiç değişmediği'], 'Net iş kinetik enerji değişimine eşittir; net iş sıfırsa kinetik enerji, dolayısıyla sürat değişmemiştir. Hızın yönü ise değişmiş olabilir.'),
  ('Sürtünmesiz yatay bir düzlemde duran 5 kg\'lık bir cisme ileri yönde 50 N, geri yönde 20 N\'luk iki yatay kuvvet etki ediyor. Cisim 3 m yol aldığında sürati kaç m/s olur?', '6 m/s', ['3 m/s', '9 m/s', '12 m/s'], 'Net kuvvet 30 N, net iş 30·3 = 90 J\'dür. ½·5·v² = 90 eşitliğinden v² = 36, v = 6 m/s bulunur.'),
  ('Bir aracın sürati %10 artırılırsa kinetik enerjisi yüzde kaç artar?', '%21', ['%10', '%20', '%100'], 'Kinetik enerji süratin karesiyle orantılıdır: 1,1² = 1,21. Bu nedenle enerji %21 artar.'),
  ('Hareket eden bir trende koltuğunda oturan yolcunun kucağındaki çantanın kinetik enerjisi, yolcuya göre sıfır, raydaki gözlemciye göre sıfırdan büyüktür. Bu durum kinetik enerji için neyi gösterir?', 'Değerinin seçilen gözlem çerçevesine bağlı olduğunu', ['Enerjinin korunmadığını', 'Çantanın kütlesinin çerçeveye göre değiştiğini', 'Kinetik enerjinin yönü olan vektörel bir nicelik olduğunu'], 'Hız çerçeveye göre değiştiğinden ½mv² de çerçeveye bağlıdır; her çerçevede enerjinin korunumu ayrı ayrı geçerlidir.'),
  ('Kütlesi 0,5 kg olan bir çekiç 8 m/s hızla bir çiviye vuruyor ve çivi tahtaya 2 cm giriyor. Çekicin tüm kinetik enerjisinin çiviyi itmekte kullanıldığı varsayılırsa tahtanın ortalama direnci kaç newton\'dur?', '800 N', ['80 N', '160 N', '1600 N'], 'Çekicin enerjisi ½·0,5·64 = 16 J\'dür. F = E / d = 16 / 0,02 = 800 N.'),
  ('Kütlesi 45 g olan bir golf topu sopadan 70 m/s hızla çıkıyor. Topun kinetik enerjisi yaklaşık kaç joule\'dür?', '110 J', ['1,6 J', '3150 J', '220 J'], 'E_k = ½·0,045·70² = 0,0225·4900 ≈ 110 J.'),
  ('Kütlesi 5000 kg olan bir fil 1 m/s ile yürüyor, kütlesi 10 g olan bir mermi ise 800 m/s ile uçuyor. Kinetik enerjileri için hangisi doğrudur?', 'Merminin kinetik enerjisi daha büyüktür', ['Filin kinetik enerjisi daha büyüktür', 'İkisinin kinetik enerjisi eşittir', 'Kütleler farklı olduğundan karşılaştırılamaz'], 'Fil: ½·5000·1² = 2500 J. Mermi: ½·0,01·800² = 3200 J. Hızın karesi etkisi merminin enerjisini büyük kılar.'),
  ('Bir otomobili 0\'dan 50 km/h\'e hızlandırmak için gereken net iş W ise aynı otomobili 50 km/h\'ten 100 km/h\'e hızlandırmak için gereken net iş kaç W\'dir?', '3W', ['W', '1,5W', '4W'], 'Kinetik enerji süratin karesiyle orantılıdır: 100 km/h\'teki enerji 4W\'dir. Aradaki fark 4W − W = 3W olur.'),
  ('Kütlesi 1 g olan bir yağmur damlası yere 9 m/s sabit (limit) süratle ulaşıyor. Damlanın yere çarpma anındaki kinetik enerjisi kaç joule\'dür?', '0,0405 J', ['4,05 J', '0,081 J', '0,00405 J'], 'E_k = ½·0,001·81 = 0,0405 J = 4,05 × 10⁻² J.'),
  ('Kütlesi m olan bir cisme, hareket yönünde etki eden sabit bir F kuvveti d yolu boyunca iş yapıyor. Cisim durgun hâlden başladıysa son sürati hangi ifadeyle verilir?', '√(2Fd/m)', ['2Fd/m', '√(Fd/(2m))', 'Fd/m'], 'Fd = ½mv² eşitliğinden v² = 2Fd/m, v = √(2Fd/m) bulunur.'),
  ('Bir kitap elle yukarı doğru sabit hızla kaldırılırken kitaba etki eden kuvvetlerin net işi için hangisi doğrudur?', 'Sıfırdır; elin pozitif işini çekimin negatif işi dengeler', ['Pozitiftir; çünkü kitabın enerjisi artmaktadır', 'Negatiftir; çünkü çekim kuvveti iş yapmaktadır', 'Elin yaptığı işe eşittir; çünkü çekim kuvveti hiç iş yapmaz'], 'Sürat değişmediğinden kinetik enerji değişimi ve dolayısıyla net iş sıfırdır. El +mgh, çekim −mgh iş yapar; kitabın potansiyel enerjisi elin işi kadar artar.'),
  ('Kütlesi 3 kg olan bir saksı 8 m yükseklikteki bir balkondan 2 m yükseklikteki bir sundurmaya düşüyor. Sıfır düzeyi olarak yerden 5 m yükseklikteki bir pencere seçilirse saksının çekim potansiyel enerjisindeki değişim kaç joule\'dür? (g = 10 m/s²)', '−180 J', ['−90 J', '+180 J', '−1800 J'], 'Değişim referanstan bağımsızdır: ΔE_p = mgΔh = 3·10·(2 − 8) = −180 J. Başlangıçta +90 J, sonda −90 J bulunur.'),
  ('Yerde yatan 2 m uzunluğunda, 10 kg kütleli düzgün bir direk bir ucundan kaldırılarak düşey konuma getiriliyor. Bunun için yapılması gereken en az iş kaç joule\'dür? (g = 10 m/s²)', '100 J', ['200 J', '1000 J', '400 J'], 'Düzgün direğin kütle merkezi ortasındadır ve 1 m yükselir: W = mgh = 10·10·1 = 100 J.'),
  ('Bir yayı 4 cm uzatmak için kuvvet sıfırdan başlayarak düzgün biçimde artırılıyor ve uzama 4 cm olduğunda kuvvet 50 N\'a ulaşıyor. Yayda depolanan esneklik potansiyel enerjisi kaç joule\'dür?', '1 J', ['2 J', '0,5 J', '100 J'], 'Hooke yasasına uyan yayda depolanan enerji ½·F·x = ½·50·0,04 = 1 J\'dür.'),
  ('İp uzunluğu 2,5 m olan bir sarkaç, ip düşeyle 60° açı yapacak konumdan serbest bırakılıyor. Sarkaç topu en alt noktadan geçerken sürati kaç m/s\'dir? (g = 10 m/s², cos60° = 0,5)', '5 m/s', ['2,5 m/s', '10 m/s', '7,1 m/s'], 'Topun düştüğü yükseklik L(1 − cos60°) = 1,25 m\'dir. v = √(2gh) = √25 = 5 m/s.'),
  ('Bir sarkaç salınırken ipin topa uyguladığı gerilme kuvvetinin yaptığı iş için hangisi doğrudur?', 'İp kuvveti hep harekete dik olduğundan iş yapmaz', ['Top aşağı inerken pozitif, çıkarken negatif iş yapar', 'Topu yukarıda tuttuğu için sürekli pozitif iş yapar', 'Topun ağırlığına eşit büyüklükte negatif iş yapar'], 'Top çember yayı üzerinde hareket eder ve ip kuvveti her an yarıçap doğrultusunda, yani hıza diktir. Bu yüzden enerji yalnız çekim ile kinetik arasında değiş tokuş edilir.'),
  ('Sürtünmesiz bir lunapark treni 30 m yükseklikteki bir tepeden neredeyse durgun hâlde inişe geçiyor. Tren daha sonra 10 m yükseklikteki ikinci bir tepenin üstünden geçerken sürati kaç m/s olur? (g = 10 m/s²)', '20 m/s', ['10 m/s', '14,1 m/s', '30 m/s'], 'Düşülen net yükseklik 20 m\'dir: v = √(2·10·20) = √400 = 20 m/s.'),
  ('Yerden 20 m yükseklikten serbest bırakılan bir taşın kinetik enerjisi, hangi yükseklikte potansiyel enerjisinin 3 katı olur? (Yer referans, hava direnci yok)', '5 m', ['15 m', '10 m', '6,7 m'], 'Toplam enerji mg·20\'dir. E_k = 3E_p ise 4E_p = mg·20 olur ve mgh = mg·5, h = 5 m bulunur.'),
  ('Yerden 10 m yükseklikten 2 kg\'lık bir top 10 m/s hızla aşağı doğru fırlatılıyor. Hava direnci yoksa topun yere çarptığı andaki kinetik enerjisi kaç joule\'dür? (g = 10 m/s²)', '300 J', ['200 J', '1000 J', '400 J'], 'Başlangıç enerjisi E_k + E_p = 100 + 200 = 300 J\'dür; yerde bunun tamamı kinetik enerjiye dönüşür.'),
  ('Sürtünmesiz bir yatay düzlemde, yay sabiti 200 N/m olan bir yay 20 cm sıkıştırılıp önüne 0,5 kg\'lık bir blok konuyor. Blok serbest bırakılıp ardından sürtünmesiz bir rampaya tırmanırsa en fazla kaç cm yükselir? (g = 10 m/s²)', '80 cm', ['40 cm', '20 cm', '160 cm'], 'Yaydaki enerji ½·200·0,04 = 4 J\'dür. mgh = 4 eşitliğinden h = 4/(0,5·10) = 0,8 m = 80 cm.'),
  ('Düşey yukarı fırlatılan bir topun hava direnci yokken tepe noktasının yarı yüksekliğinden geçerken kinetik enerjisi, başlangıç kinetik enerjisinin kaçta kaçıdır?', '1/2', ['1/4', '3/4', '1/√2'], 'Yarı yükseklikte potansiyel enerji, tepedeki değerin (yani ilk kinetik enerjinin) yarısıdır; geriye kalan yarısı kinetik enerjidir.'),
  ('Aynı süratle giden ve aynı lastiklere sahip iki araçtan birinin kütlesi diğerinin iki katıdır. Tekerlekleri kilitlenerek kayan bu araçların durma mesafeleri için hangisi doğrudur? (Sürtünme katsayısı aynı)', 'Durma mesafeleri eşittir', ['Ağır aracınki iki kat uzundur', 'Hafif aracınki iki kat uzundur', 'Ağır aracınki dört kat uzundur'], '½mv² = μmgd eşitliğinde kütle sadeleşir: d = v²/(2μg). Sürat ve μ aynıysa mesafe kütleden bağımsızdır.'),
  ('Yatay bir masada 3 m/s ile kaymaya başlayan bir disk, 2 m yol aldığında sürati 1 m/s\'ye düşüyor. Disk ile masa arasındaki kinetik sürtünme katsayısı kaçtır? (g = 10 m/s²)', '0,2', ['0,1', '0,4', '0,25'], '½m(v₂² − v₁²) = −μmgd: ½(1 − 9) = −μ·10·2 → −4 = −20μ → μ = 0,2.'),
  ('Durgun hâlden sürtünmesiz bir rampadan 2 m yükseklik kadar inen bir kızak, rampanın sonundaki ve sürtünme katsayısı 0,4 olan yatay bir kum alanına giriyor. Kızak kum alanında kaç metre gidip durur?', '5 m', ['0,8 m', '2,5 m', '8 m'], 'mgh = μmgd eşitliğinden d = h/μ = 2/0,4 = 5 m. Sonuç g ve kütleden bağımsızdır.'),
  ('Uzun dağ inişlerindeki otoyollarda freni boşalan ağır taşıtlar için yokuş yukarı ve derin gevşek çakılla kaplı kaçış rampaları yapılır. Bu rampalar aracın kinetik enerjisini nasıl giderir?', 'Çekim potansiyel enerjisine ve çakılın sürtünmesiyle iç enerjiye çevirerek', ['Aracın kütlesini azaltarak enerjisini düşürür', 'Enerjiyi yolun altındaki yaylarda saklayıp geri verir', 'Aracın momentumunu yere aktarıp enerjisini olduğu gibi korur'], 'Yokuş yukarı gidiş enerjinin bir kısmını çekim potansiyel enerjisine çevirir; gevşek çakıl ise tekerlekleri gömerek kalan enerjiyi sürtünme ve şekil değiştirme yoluyla ısıya dönüştürür.'),
  ('20 m/s ile giden bir sürücünün tehlikeyi görüp frene basması 1 s sürüyor. Fren sonrası lastik ile yol arasındaki sürtünme katsayısı 0,5 ise sürücünün tehlikeyi gördüğü andan durana kadar aracın aldığı toplam yol kaç metredir? (g = 10 m/s²)', '60 m', ['40 m', '20 m', '80 m'], 'Tepki süresinde 20 m alınır. Fren mesafesi v²/(2μg) = 400/10 = 40 m\'dir. Toplam 60 m\'dir.'),
  ('Bir kayakçı sürtünmesiz kabul edilen bir yokuşun tepesinden 4 m/s ile geçiyor ve 15 m aşağıdaki düzlüğe iniyor. Düzlüğe vardığında sürati kaç m/s olur? (g = 10 m/s²)', '√316 ≈ 17,8 m/s', ['19 m/s', '20 m/s', '√300 ≈ 17,3 m/s'], 'v² = v₀² + 2gh = 16 + 300 = 316, v ≈ 17,8 m/s. Başlangıç kinetik enerjisi ihmal edilmemelidir.'),
  ('Pürüzlü yatay bir yolda belli bir süratten kilitli tekerlekle kayarak duran bir aracın kayma izinin uzunluğu ölçülüyor. Sürtünme katsayısı biliniyorsa aracın fren öncesi süratini bulmak için hangi bilgiye gerek yoktur?', 'Aracın kütlesine', ['Kayma izinin uzunluğuna', 'Yer çekimi ivmesine', 'Sürtünme katsayısına'], 'v = √(2μgd) ifadesinde kütle yer almaz; kaza incelemelerinde bu nedenle yalnız iz uzunluğu ve yol yüzeyi bilgisi kullanılır.'),
  ('Sürtünmeli bir eğik düzlemde sabit hızla aşağı kayan bir blok için hangi yargı doğrudur?', 'Çekimin işi sürtünmenin işine eşit büyüklüktedir', ['Mekanik enerjisi korunmaktadır', 'Kinetik enerjisi düzgün biçimde artmaktadır', 'Sürtünme kuvveti hiç iş yapmamaktadır'], 'Sürat sabit olduğundan net iş sıfırdır; çekimin pozitif işi sürtünmenin negatif işini dengeler. Kaybolan potansiyel enerji ısıya dönüşür.'),
  ('Yatay bir buz pistinde 6 m/s ile kaymaya başlayan bir patenci, sürtünme katsayısı 0,03 olan buzda hiç itmeden kaç metre kayabilir? (g = 10 m/s²)', '60 m', ['30 m', '120 m', '18 m'], 'd = v²/(2μg) = 36/(2·0,03·10) = 36/0,6 = 60 m.'),
  ('Motorunun yola aktardığı en büyük güç 60 kW olan bir araca düz yolda toplam 2000 N\'luk sabit direnç kuvveti etki ediyor. Aracın ulaşabileceği en büyük sürat kaç m/s\'dir?', '30 m/s', ['120 m/s', '3 m/s', '33,3 m/s'], 'En büyük süratte itici kuvvet dirence eşittir: v = P/F = 60 000/2000 = 30 m/s.'),
  ('Kütlesi 1000 kg olan bir araç, her 100 m yolda 10 m yükselen bir yokuşu sabit 10 m/s süratle çıkıyor. Sürtünme ve hava direnci ihmal edilirse motorun yalnız yükselmek için verdiği güç kaç kW\'tır? (g = 10 m/s²)', '10 kW', ['100 kW', '1 kW', '5 kW'], 'Düşey hız bileşeni 10·0,1 = 1 m/s\'dir. Güç P = mg·v_düşey = 10 000·1 = 10 000 W = 10 kW.'),
  ('Kütlesi 1000 kg olan bir otomobil 10 s içinde durgun hâlden 30 m/s\'ye çıkıyor. Kayıplar ihmal edilirse motorun bu sürede verdiği ortalama güç kaç kW\'tır?', '45 kW', ['30 kW', '90 kW', '4,5 kW'], 'Kazanılan kinetik enerji ½·1000·900 = 450 000 J\'dür. Ortalama güç 450 000/10 = 45 000 W.'),
  ('Sabit 50 kW güç veren bir motor, kayıpların ihmal edildiği düz bir yolda 1000 kg\'lık bir aracı durgun hâlden 20 m/s\'ye kaç saniyede çıkarır?', '4 s', ['2 s', '8 s', '0,4 s'], 'Gereken enerji ½·1000·400 = 200 000 J\'dür. Sabit güçte süre t = E/P = 200 000/50 000 = 4 s.'),
  ('Otomobil kataloglarında görülen metrik beygir gücü (PS) yaklaşık kaç watt\'a eşittir?', '735,5 W', ['746 W', '1000 W', '550 W'], 'Metrik beygir gücü 75 kgf·m/s olarak tanımlanır ve yaklaşık 735,5 W\'tır. 746 W ise İngiliz (mekanik) beygir gücüdür.'),
  ('Güç biriminin watt\'ın SI temel birimleri cinsinden karşılığı hangisidir?', 'kg·m²/s³', ['kg·m²/s²', 'kg·m/s³', 'kg·m²/s'], '1 W = 1 J/s ve 1 J = 1 kg·m²/s² olduğundan 1 W = 1 kg·m²/s³ olur.'),
  ('Kütlesi 70 kg olan bir dağcı, sırt çantasının kütlesi ihmal edilirse 1 saatte 500 m düşey yükseliyor. Dağcının yalnız yükselmek için harcadığı ortalama güç yaklaşık kaç watt\'tır? (g = 10 m/s²)', '97 W', ['350 W', '9,7 W', '583 W'], 'Yapılan iş mgh = 70·10·500 = 350 000 J\'dür. P = 350 000/3600 ≈ 97 W.'),
  ('Bir alışveriş merkezindeki yürüyen merdiven her dakika ortalama 70 kg\'lık 20 kişiyi 6 m yukarı taşıyor. Kayıplar ihmal edilirse merdivenin yük için verdiği güç kaç watt\'tır? (g = 10 m/s²)', '1400 W', ['84 000 W', '140 W', '2800 W'], 'Bir dakikadaki iş 20·70·10·6 = 84 000 J\'dür. P = 84 000/60 = 1400 W.'),
  ('Bir motorun gücünün zamanla nasıl değiştiği biliniyorsa belli bir aralıkta yaptığı toplam iş nasıl bulunur?', 'Güç-zaman eğrisinin altındaki alan hesaplanarak', ['Gücün en büyük değeri süreye bölünerek', 'Gücün o aralıktaki eğimi alınarak', 'Başlangıç ve son güçlerin farkı alınarak'], 'W = ∫P dt olduğundan iş, güç-zaman eğrisinin altında kalan alana eşittir; güç sabitse bu alan P·t olur.'),
  ('Verimi %40 olan bir santralde üretilen elektrik, %90 verimli hatlarla bir fabrikaya iletiliyor ve orada %80 verimli bir motorla mekanik işe çevriliyor. Santrale giren yakıt enerjisinin yüzde kaçı mekanik işe dönüşür?', '%28,8', ['%40', '%70', '%36'], 'Ardışık aşamalarda verimler çarpılır: 0,40 × 0,90 × 0,80 = 0,288.'),
  ('Bir barajda türbinlerden saniyede 100 m³ su 50 m yükseklik farkıyla akıyor. Santralin toplam verimi %90 ise elektrik gücü kaç MW\'tır? (Suyun yoğunluğu 1000 kg/m³, g = 10 m/s²)', '45 MW', ['50 MW', '4,5 MW', '450 MW'], 'Suyun saniyede kaybettiği potansiyel enerji ṁgh = 100 000·10·50 = 5·10⁷ W\'tır. %90\'ı: 4,5·10⁷ W = 45 MW.'),
  ('Bir rüzgâr türbininin kanat boyu iki katına çıkarılırsa aynı rüzgâr hızında türbinin yakalayabileceği güç kaç katına çıkar?', '4 katına', ['2 katına', '8 katına', '16 katına'], 'Rüzgâr gücü ½ρAv³ ile verilir; süpürülen alan A, kanat boyunun karesiyle orantılı olduğundan güç 4 katına çıkar.'),
  ('Dinlenen bir yetişkinin vücudu günde yaklaşık 2000 kcal enerji harcıyor. Bu, ortalama olarak yaklaşık kaç watt\'lık güce karşılık gelir? (1 kcal ≈ 4186 J)', '100 W', ['2000 W', '10 W', '1000 W'], 'Günlük enerji 2000·4186 ≈ 8,4·10⁶ J\'dür. Bir günde 86 400 s vardır: P ≈ 8,4·10⁶/86 400 ≈ 97 W ≈ 100 W.'),
  ('İnsan kaslarının besinden aldığı kimyasal enerjiyi dışarıya yapılan mekanik işe çevirme verimi en fazla yaklaşık ne kadardır?', '%25', ['%90', '%60', '%5'], 'Kasların mekanik verimi en iyi durumda yaklaşık %20–25\'tir; enerjinin geri kalanı ısıya dönüşür. Bu yüzden egzersizde vücut ısınır.'),
  ('Elektrik motorundan 5 kW güç çeken bir su pompasının verimi %80\'dir. Pompa 1 dakikada 20 m yükseğe kaç kg su basabilir? (g = 10 m/s²)', '1200 kg', ['1500 kg', '20 kg', '15 000 kg'], 'Yararlı güç 4000 W\'tır; 60 s\'de 240 000 J yararlı iş yapılır. m = 240 000/(10·20) = 1200 kg.'),
  ('Bir inşaat vinci 2 tonluk bir yükü 1 dakikada sabit hızla 30 m yükseltiyor. Vincin verimi %75 ise motorun çektiği güç yaklaşık kaç kW\'tır? (g = 10 m/s²)', '13,3 kW', ['10 kW', '7,5 kW', '800 kW'], 'Yararlı güç 20 000·30/60 = 10 000 W\'tır. Çekilen güç 10 000/0,75 ≈ 13 333 W ≈ 13,3 kW.'),
  ('1 kilowatt-saat elektrik enerjisi yaklaşık kaç kilokaloriye eşittir? (1 kcal ≈ 4186 J)', '860 kcal', ['3600 kcal', '1000 kcal', '86 kcal'], '1 kWh = 3,6·10⁶ J\'dür. 3,6·10⁶/4186 ≈ 860 kcal.'),
  ('Pompalı depolamalı hidroelektrik santrallerinde elektrik talebinin düşük olduğu saatlerde ne yapılır?', 'Su, alttaki gölden üstteki göle pompalanır', ['Türbinler tam güçle çalıştırılır', 'Barajın kapakları tamamen açılır', 'Gölün suyu ısıtılarak buhar türbinlerine gönderilir'], 'Artan elektrikle su yukarı pompalanıp çekim potansiyel enerjisi olarak depolanır; talep yükselince bu su türbinlerden geçirilerek yeniden elektrik üretilir.'),
  ('Bir pompalı depolama tesisi suyu yukarı basarken %85, suyu geri indirip elektrik üretirken %90 verimle çalışıyor. Depolanan her 100 MWh elektrik için geri alınan enerji yaklaşık kaç MWh\'tir?', '76,5 MWh', ['87,5 MWh', '90 MWh', '75 MWh'], 'Gidiş-dönüş verimi iki verimin çarpımıdır: 0,85·0,90 = 0,765. 100 MWh\'nin 76,5 MWh\'i geri alınır.'),
  ('Bir kaldıraçla 400 N\'luk bir yük 0,2 m kaldırılırken kola 100 N kuvvet uygulanıyor ve kolun ucu 1 m iniyor. Kaldıracın verimi yüzde kaçtır?', '%80', ['%100', '%25', '%400'], 'Yararlı iş 400·0,2 = 80 J, verilen iş 100·1 = 100 J\'dür. Verim 80/100 = %80.'),
  ('Bir bilardo topu bandaya eğik çarpıp aynı süratle yansıyor. Topun momentum değişiminin yönü için hangisi doğrudur?', 'Bandaya dik ve masanın içine doğrudur', ['Bandaya paralel ve topun ilk hareketi yönündedir', 'Topun ilk hızıyla aynı yöndedir', 'Topun yansıma hızıyla aynı yöndedir'], 'Bandaya paralel momentum bileşeni korunur, yalnız dik bileşen tersine döner. Bu nedenle momentum değişimi ve bandanın uyguladığı kuvvet bandaya diktir.'),
  ('Bir cisme uygulanan kuvvet 0,1 s içinde sıfırdan 400 N\'a düzgün olarak artıyor, sonraki 0,1 s içinde yine düzgün olarak sıfıra iniyor. Cisme verilen toplam itme kaç N·s\'dir?', '40 N·s', ['80 N·s', '20 N·s', '400 N·s'], 'İtme, kuvvet-zaman eğrisinin altındaki alandır; burada taban 0,2 s, yükseklik 400 N olan üçgen: ½·0,2·400 = 40 N·s.'),
  ('Aynı yükseklikten düşen iki özdeş yumurtadan biri betona çarparak 0,001 s\'de, diğeri yumuşak bir yastığa düşerek 0,1 s\'de duruyor. Betondaki ortalama durdurucu kuvvet yastıktakinin yaklaşık kaç katıdır?', '100 katı', ['10 katı', '1 katı', '1000 katı'], 'İki yumurtanın momentum değişimi aynıdır. Ortalama kuvvet süreyle ters orantılı olduğundan 0,1/0,001 = 100 kat büyüktür.'),
  ('Kütlesi 1 kg olan bir cisim yatay düzlemde 4 m/s sabit süratle çember üzerinde dönüyor. Cisim çemberin yarısını dolaştığında momentumundaki değişimin büyüklüğü kaç kg·m/s olur?', '8 kg·m/s', ['0 kg·m/s', '4 kg·m/s', '5,7 kg·m/s'], 'Yarım turda hız tam tersine döner: Δp = mv − (−mv) = 2mv = 8 kg·m/s. Sürat sabit olsa da momentum vektörü değişir.'),
  ('Kütlesi 0,5 kg olan bir top 5 m yükseklikten bırakılıyor; yere 10 m/s ile çarpıp 6 m/s ile yukarı sekiyor. Topun çarpma sırasındaki momentum değişiminin büyüklüğü kaç kg·m/s\'dir?', '8 kg·m/s', ['2 kg·m/s', '16 kg·m/s', '3 kg·m/s'], 'Yönler zıt olduğundan Δp = 0,5·6 − (−0,5·10) = 3 + 5 = 8 kg·m/s.'),
  ('Bir otoparkın çatısına her saniye 2 kg yağmur suyu 10 m/s düşey süratle düşüyor ve sıçramadan duruyor. Damlaların durdurulması nedeniyle çatıya etki eden ortalama ek kuvvet kaç newton\'dur?', '20 N', ['5 N', '2 N', '200 N'], 'Çatı her saniye 2·10 = 20 kg·m/s momentumu yok eder; F = Δp/Δt = 20 N.'),
  ('Bir bahçe hortumundan saniyede 0,5 kg su 20 m/s hızla yatay çıkıp bir duvara dik çarpıyor ve duvardan geri sıçramadan aşağı akıyor. Suyun duvara uyguladığı yatay kuvvet kaç newton\'dur?', '10 N', ['20 N', '400 N', '5 N'], 'Saniyede yok edilen yatay momentum 0,5·20 = 10 kg·m/s\'dir; bu da 10 N\'luk kuvvete karşılık gelir.'),
  ('Bir hortumdan çıkan su jeti duvara dik çarpıp tamamen aynı süratle geri sıçrasaydı, suyun geri sıçramadan aşağı aktığı duruma göre duvara uygulanan kuvvet nasıl olurdu?', 'İki katına çıkardı', ['Aynı kalırdı', 'Yarıya inerdi', 'Dört katına çıkardı'], 'Geri sıçramada her su kütlesinin momentum değişimi mv yerine 2mv olur; kuvvet momentum değişim hızına eşit olduğundan iki katına çıkar.'),
  ('Kütlesi 0,15 kg olan bir beyzbol topu atıcıdan 40 m/s ile geliyor ve sopayla 1 ms süren temastan sonra ters yönde 50 m/s ile uzaklaşıyor. Sopanın topa uyguladığı ortalama kuvvet kaç newton\'dur?', '13 500 N', ['1500 N', '135 000 N', '7500 N'], 'Δp = 0,15·(50 + 40) = 13,5 kg·m/s\'dir. F = 13,5/0,001 = 13 500 N.'),
  ('Durgun duran 3 kg\'lık bir cisim patlayarak 1 kg ve 2 kg\'lık iki parçaya ayrılıyor. 1 kg\'lık parça 6 m/s ile uçtuğuna göre patlamada açığa çıkan kinetik enerji kaç joule\'dür?', '27 J', ['18 J', '36 J', '13,5 J'], 'Momentum korunumundan 2 kg\'lık parça 3 m/s ile zıt yöne gider. Toplam kinetik enerji ½·1·36 + ½·2·9 = 18 + 9 = 27 J.'),
  ('Doğuya 10 m/s ile giden 4 kg\'lık bir cisim iç patlamayla iki eşit parçaya ayrılıyor ve parçalardan biri yere göre durgun kalıyor. Diğer parçanın hızı nedir?', 'Doğuya 20 m/s', ['Doğuya 10 m/s', 'Batıya doğru 20 m/s', 'Doğuya 40 m/s'], 'Toplam momentum 40 kg·m/s korunur; 2 kg\'lık hareketli parça 40 = 2·v eşitliğinden 20 m/s ile doğuya gider.'),
  ('Havaya eğik atılan bir havai fişek, uçuşunun tepe noktasında çok sayıda parçaya patlıyor. Hava direnci ihmal edilirse parçaların kütle merkezi patlamadan sonra nasıl hareket eder?', 'Patlama olmamış gibi aynı parabolü izler', ['Patlama noktasında durup düşey olarak düşer', 'Patlama noktasında kalıp asılı durur', 'Düz bir çizgide yatay olarak gider'], 'Patlama kuvvetleri iç kuvvetlerdir; sisteme etkiyen tek dış kuvvet yine çekimdir. Bu nedenle kütle merkezi aynı parabolik yörüngeyi sürdürür.'),
  ('Bir doğru üzerinde 2 kg\'lık bir cisim sağa 3 m/s, 3 kg\'lık başka bir cisim sola 2 m/s hızla hareket ediyor. Bu iki cisimden oluşan sistemin kütle merkezinin hızı kaç m/s\'dir?', '0', ['1 m/s', '2,5 m/s', '0,4 m/s'], 'v_km = (2·3 + 3·(−2))/(2 + 3) = 0/5 = 0. Sistemin toplam momentumu sıfır olduğundan kütle merkezi durgundur.'),
  ('Bir sistemin parçaları arasında etkileşen iç kuvvetler (çarpışma, patlama, yay itmesi) sistemin kütle merkezinin ivmesini nasıl etkiler?', 'Hiç etkilemez; ivmeyi yalnız dış kuvvetler belirler', ['Kütle merkezini iç kuvvet yönünde hızlandırır', 'Kütle merkezini her zaman durdurur', 'İç kuvvetler büyükse kütle merkezini yön değiştirir'], 'İç kuvvetler etki-tepki çiftleri olduğundan toplamları sıfırdır; kütle merkezinin ivmesi M·a_km = ΣF_dış ile yalnız dış kuvvetlere bağlıdır.'),
  ('Sürtünmesiz raylarda 2 m/s ile giden 100 kg\'lık bir vagonun üzerinde 50 kg\'lık bir kişi var. Kişi geriye doğru atlayarak yere göre tam durgun hâle geliyor. Vagonun yeni sürati kaç m/s olur?', '3 m/s', ['2 m/s', '4 m/s', '1,33 m/s'], 'Toplam momentum (150·2 = 300 kg·m/s) korunur; kişinin momentumu sıfır olduğundan 300 = 100·v, v = 3 m/s.'),
  ('Durgun bir cisim patlayarak kütleleri farklı iki parçaya ayrılıyor. Parçaların kinetik enerjileri için hangisi doğrudur?', 'Hafif parça daha fazla kinetik enerji alır', ['Ağır parça daha fazla kinetik enerji alır', 'İki parçanın kinetik enerjileri eşittir', 'Enerjiler kütlelerle doğru orantılı paylaşılır'], 'Parçaların momentumları eşit büyüklüktedir; E = p²/(2m) olduğundan kinetik enerji kütleyle ters orantılı paylaşılır.'),
  ('Hafif bir top, durgun ve çok ağır bir cisme (örneğin bir duvara) merkezî ve esnek olarak çarpıyor. Çarpışmadan sonra topun hareketi için hangisi doğrudur?', 'Yaklaşık aynı süratle geri döner', ['Durur ve ağır cismin yanında kalır', 'Süratini iki katına çıkararak geri döner', 'Süratinin yarısıyla aynı yönde ilerler'], 'm₂ ≫ m₁ olduğunda v₁\' = (m₁ − m₂)v₁/(m₁ + m₂) ≈ −v₁ olur; ağır cisim neredeyse hareketsiz kalır.'),
  ('Çarpışma (geri sıçrama) katsayısı e olan bir çarpışmada e = 0 olması neyi gösterir?', 'Cisimlerin çarpışmadan sonra birlikte hareket ettiğini', ['Kinetik enerjinin tamamen korunduğunu', 'Cisimlerin çarpışmadan sonra aynı süratle geri döndüğünü', 'Momentumun korunmadığını'], 'e = 0 için ayrılma hızı sıfırdır; cisimler yapışır ve kinetik enerji kaybı en büyük olur. e = 1 ise çarpışma esnektir.'),
  ('Bir otoyolda 20 m/s ile giden 1200 kg\'lık bir otomobil, aynı yönde 10 m/s ile giden 800 kg\'lık bir otomobile arkadan çarpıyor ve araçlar kenetleniyor. Çarpışmadan hemen sonra ortak hızları kaç m/s olur?', '16 m/s', ['15 m/s', '10 m/s', '30 m/s'], 'Momentum korunumu: (1200·20 + 800·10)/2000 = 32 000/2000 = 16 m/s.'),
  ('Kütlesi 10 g olan bir mermi 500 m/s ile, sürtünmesiz yüzeyde duran 2 kg\'lık tahta bloğu delip 200 m/s ile çıkıyor. Bloğun kazandığı hız kaç m/s\'dir?', '1,5 m/s', ['2,5 m/s', '3,5 m/s', '1 m/s'], 'Merminin kaybettiği momentum 0,01·300 = 3 kg·m/s\'dir ve bloğa geçer: V = 3/2 = 1,5 m/s.'),
  ('Balistik sarkaç çözümünde merminin bloğa saplandığı çarpışma anı için mekanik enerjinin korunumu neden kullanılamaz?', 'Saplanma esnek değildir; enerjinin bir kısmı ısıya dönüşür', ['Çarpışma anında momentum da korunmadığı için', 'İp gerilmesi çarpışmada büyük bir iş yaptığı için', 'Çarpışmada çekim potansiyel enerjisi aniden ve büyük ölçüde arttığı için'], 'Saplanma tam esnek olmayan bir çarpışmadır: yalnız momentum korunur. Enerji korunumu ancak çarpışmadan sonraki yükselme aşamasında kullanılabilir.'),
  ('Esnek olmayan bir çarpışmada toplam momentum korunduğu hâlde toplam kinetik enerjinin korunmamasının nedeni nedir?', 'İç kuvvetler korunumsuzdur; enerjiyi ısıya ve biçim değişimine çevirir', ['Çarpışmada dış kuvvetlerin momentumu değiştirmesi', 'Kinetik enerjinin vektörel olup yön değiştirmesi', 'Cisimlerin kütlelerinin çarpışma sırasında ısı nedeniyle bir miktar azalması'], 'İç kuvvetler etki-tepki çifti olduğundan momentum korunur; ancak bu kuvvetler korunumsuzsa (ezilme, sürtünme) kinetik enerji iç enerjiye dönüşebilir.'),
  ('Zıt yönlerde hareket eden 2 kg\'lık bir cisim (5 m/s) ile 3 kg\'lık bir cisim (5 m/s) çarpışıp yapışıyor. Ortak hızın büyüklüğü ve yönü nedir?', '1 m/s, 3 kg\'lık cismin ilk yönünde', ['1 m/s, 2 kg\'lık cismin ilk yönünde', '5 m/s, 3 kg\'lık cismin ilk yönünde', 'Sıfır, çünkü süratler eşittir'], 'Momentumlar 10 ve −15 kg·m/s\'dir; toplam −5 kg·m/s. Ortak hız −5/5 = −1 m/s, yani ağır cismin yönündedir.'),
  ('İnce cidarlı bir halka düz bir yolda kaymadan yuvarlanıyor. Halkanın dönme kinetik enerjisi ile öteleme kinetik enerjisi arasındaki ilişki nedir? (I = mr²)', 'Birbirine eşittir', ['Dönme enerjisi iki katıdır', 'Öteleme enerjisi iki katıdır', 'Dönme enerjisi sıfırdır'], 'Halkada ½Iω² = ½mr²(v/r)² = ½mv² olur; dönme ve öteleme enerjileri eşittir.'),
  ('Aynı yükseklikteki bir eğik düzlemden sürtünmesiz kayan bir buz küpü ile kaymadan yuvarlanan bir bilye bırakılıyor. Düzlemin dibine hangisi daha büyük süratle ulaşır?', 'Kayan buz küpü', ['Yuvarlanan bilye', 'İkisi aynı süratle ulaşır', 'Kütlesi büyük olan'], 'Buz küpünün bütün potansiyel enerjisi öteleme enerjisine dönüşür; bilyenin enerjisinin bir kısmı ise dönmeye gider. Bu yüzden bilyenin öteleme sürati daha küçüktür.'),
  ('Enerji depolamakta kullanılan bir volanın (eylemsizlik tekeri) eylemsizlik momenti 10 kg·m², açısal hızı 100 rad/s\'dir. Volanda depolanan dönme kinetik enerjisi kaç kJ\'dür?', '50 kJ', ['100 kJ', '1 kJ', '500 kJ'], 'E = ½Iω² = ½·10·100² = 50 000 J = 50 kJ.'),
  ('Bir yo-yo ipine sarılı olarak bırakıldığında aynı yükseklikten serbest düşen bir taştan daha yavaş iner. Bunun enerji açısından açıklaması nedir?', 'Kaybedilen potansiyel enerjinin bir kısmı dönme enerjisine gider', ['Yo-yonun kütlesi taşınkinden küçüktür', 'İp, yo-yonun potansiyel enerjisini sıfırlar', 'Yo-yo üzerine hava kaldırma kuvveti etki eder'], 'Yo-yo inerken hem öteleme hem dönme kinetik enerjisi kazanır; potansiyel enerji ikisi arasında paylaşıldığından öteleme sürati daha küçük kalır.'),
  ('Bir anahtarla bir civataya 10 N·m\'lik sabit tork uygulanarak civata 2 tam tur döndürülüyor. Torkun yaptığı iş yaklaşık kaç joule\'dür? (π ≈ 3,14)', '126 J', ['20 J', '63 J', '40 J'], 'Dönmede iş W = τ·θ\'dır. 2 tur 4π rad\'dır: W = 10·4π ≈ 125,7 J.'),
  ('Kepler\'in ikinci yasası olan ‘eşit zamanlarda eşit alanlar taranır’ ilkesi hangi korunum yasasının doğrudan sonucudur?', 'Gezegenin açısal momentumunun korunumu', ['Gezegenin çizgisel momentumunun korunumu', 'Gezegenin kinetik enerjisinin korunumu', 'Gezegenin kütlesinin korunumu'], 'Güneş\'in çekim kuvveti merkezîdir ve gezegene Güneş\'e göre tork uygulamaz. Açısal momentum sabit kaldığından alan tarama hızı da sabittir.'),
  ('Atlama tahtasından atlayan bir dalgıç, havada dizlerini göğsüne çekerek takla hızını artırıyor; suya girmeden önce vücudunu yeniden açıyor. Vücudunu açtığında hangi nicelik değişmeden kalır? (Hava direnci yok)', 'Açısal momentumu', ['Açısal hızı', 'Dönme kinetik enerjisi', 'Eylemsizlik momenti'], 'Havada dalgıca tork etki etmez (çekim kütle merkezine etki eder); bu yüzden açısal momentum sabittir. Vücut açılınca eylemsizlik momenti artar, açısal hız ve dönme enerjisi azalır.'),
  ('Bir kuyuda kovanın ipi, serbestçe dönebilen kütleli bir makaranın üzerinden geçiyor. Kova serbestçe inerken suya çarpma sürati, makara kütlesiz olsaydı elde edilecek değere göre nasıl olur?', 'Daha küçük olur', ['Daha büyük olur', 'Değişmez', 'Sıfır olur'], 'Kovanın kaybettiği potansiyel enerjinin bir kısmı makaranın dönme kinetik enerjisine aktarılır; kovanın öteleme kinetik enerjisi bu yüzden azalır.'),
  ('Kütleçekim potansiyel enerjisi U = −GMm/r biçiminde, sonsuz uzaklık sıfır düzeyi seçilerek yazılır. Bu durumda bir uydunun potansiyel enerjisinin negatif olması neyi anlatır?', 'Uydunun gezegene bağlı olduğunu, kurtulmak için enerji gerektiğini', ['Uydunun kütlesinin negatif olduğunu', 'Çekim kuvvetinin uyduyu ittiğini', 'Uydunun kinetik enerjisinin de bu durumda negatif olması gerektiğini'], 'Sonsuzdaki potansiyel enerji sıfırdır; gezegene yakınken enerji bunun altındadır. Uydu ancak dışarıdan enerji alırsa sıfır düzeyine, yani serbest hâle ulaşabilir.'),
  ('Bir gezegenin yüzeyinden kaçış hızının, aynı gezegenin yüzeyine çok yakın dairesel yörüngedeki dolanma hızına oranı kaçtır?', '√2', ['2', '1/√2', '√3'], 'Kaçış hızı √(2GM/R), yüzeye yakın yörünge hızı √(GM/R)\'dir; oranları √2\'dir. Dünya için yaklaşık 11,2 km/s ve 7,9 km/s\'dir.'),
  ('Çekim potansiyel enerjisindeki değişimi mgh ile hesaplamak hangi durumda yeterince doğru sonuç verir?', 'Yükseklik farkı gezegen yarıçapına göre çok küçükse', ['Cismin kütlesi çok büyükse', 'Cisim gezegenden birkaç yarıçap kadar uzaklaşıyorsa', 'Cisim çok yüksek süratle atılıyorsa'], 'mgh ifadesi, çekim kuvvetinin yükseklikle değişmediği varsayımına dayanır; bu ancak h ≪ R olduğunda geçerlidir.'),
  ('Yay sabiti 100 N/m olan bir yaya bağlı 1 kg\'lık bir cisim sürtünmesiz yatay düzlemde 10 cm genlikle salınıyor. Cismin en büyük sürati kaç m/s\'dir?', '1 m/s', ['10 m/s', '0,1 m/s', '0,5 m/s'], 'Toplam enerji ½kA² = ½·100·0,01 = 0,5 J\'dür. Dengeden geçerken bu enerji tamamen kinetiktir: ½·1·v² = 0,5, v = 1 m/s.'),
  ('Bir yay-kütle sistemi A genliğiyle salınıyor. Cisim denge konumundan A/2 uzaklıktayken kinetik enerjisi toplam enerjinin ne kadarıdır?', '3/4\'ü', ['1/2\'si', '1/4\'ü', '1/3\'ü'], 'Esneklik enerjisi ½k(A/2)² = ¼·½kA²\'dir, yani toplamın 1/4\'ü. Kalan 3/4\'ü kinetik enerjidir.'),
  ('Bir cismin potansiyel enerjisinin konuma göre değişiminde, potansiyel enerjinin yerel bir minimum yaptığı nokta için hangisi doğrudur?', 'Cisme etki eden net kuvvet sıfırdır ve denge kararlıdır', ['Cismin kinetik enerjisi her zaman sıfırdır', 'Net kuvvet en büyük değerine ulaşır', 'Denge kararsızdır; cisim en küçük itmede bile hemen uzaklaşır'], 'F = −dU/dx olduğundan minimumda kuvvet sıfırdır; cisim biraz uzaklaşınca kuvvet onu geri çeker, yani denge kararlıdır.'),
  ('Bir roket motoru saniyede 50 kg yanmış gazı, rokete göre 2000 m/s hızla geriye püskürtüyor. Motorun ürettiği itki kuvveti kaç kN\'dur?', '100 kN', ['40 kN', '25 kN', '1000 kN'], 'İtki, birim zamanda gaza verilen momentuma eşittir: F = ṁ·u = 50·2000 = 100 000 N = 100 kN.'),
  ('Uzay roketlerinin birkaç kademeli yapılmasının ve yakıtı biten kademelerin atılmasının temel nedeni hangisidir?', 'Hızlandırılacak boş kütleyi azaltıp aynı itkiyle daha çok hız kazanmak', ['Atılan kademelerin rokete ek itki vermesi', 'Roketin hava direncini tamamen yok etmek', 'Yakıtın yanma sıcaklığını yükseltmek'], 'Boş tanklar ve motorlar taşınmaya devam ederse kalan yakıt bu ölü kütleyi de hızlandırmak zorunda kalır. Kademeleri atmak kütleyi düşürür ve son hızı artırır.'),
  ('Sürtünmesiz raylarda sabit hızla giden üstü açık boş bir vagona düşey olarak yağmur yağıyor ve su vagonda birikiyor. Vagonun hızı nasıl değişir?', 'Azalır', ['Artar', 'Değişmez', 'Önce artar sonra azalır'], 'Düşey düşen yağmurun yatay momentumu yoktur. Yatay momentum korunurken toplam kütle arttığından yatay hız azalır.'),
  ('1847\'de yayımladığı ‘Kuvvetin Korunumu Üzerine’ adlı çalışmasıyla enerjinin korunumu ilkesini genel bir doğa yasası olarak matematiksel biçimde ortaya koyan Alman bilim insanı kimdir?', 'Hermann von Helmholtz', ['Rudolf Clausius', 'Gustav Kirchhoff', 'Heinrich Hertz'], 'Helmholtz, mekanik, ısı, elektrik ve manyetizma süreçlerinde ‘kuvvet’ (bugünkü adıyla enerji) toplamının korunduğunu savunmuştur.'),
  ('James Watt\'ın ‘beygir gücü’ birimini tanımlamasının pratik amacı neydi?', 'Buhar makinelerinin gücünü, yerini alacakları atlarla karşılaştırmak', ['Atların taşıyabileceği yük ağırlığını ölçmek', 'Elektrik motorlarının verimini belirlemek', 'Gemilerin yakıt tüketimini hesaplamak'], 'Watt, makinesini satın alacak maden ve fabrika sahiplerine, makinenin kaç atın işini göreceğini anlatabilmek için beygir gücünü tanımlamıştır.'),
  ('Sırıkla atlamada sporcunun koşu enerjisinin tamamı çekim potansiyel enerjisine dönüşseydi, 10 m/s ile koşan bir atlet kütle merkezini kaç metre yükseltebilirdi? (g = 10 m/s²)', '5 m', ['10 m', '2,5 m', '1 m'], '½mv² = mgh eşitliğinden h = v²/(2g) = 100/20 = 5 m. Kalkıştaki kütle merkezi yüksekliği eklenince gerçek rekorlar 6 m civarındadır.'),
  ('Yüksek atlamada kullanılan Fosbury tekniğinde (sırtüstü atlayış) sporcunun vücudunu çıtanın üzerinde kavis yaptırmasının enerji açısından yararı nedir?', 'Kütle merkezi çıtanın altından geçebildiği için daha az potansiyel enerji gerekir', ['Vücudun kütlesini azaltarak gereken enerjiyi düşürür', 'Hava direncini sıfırlayarak enerji kazandırır', 'Sırtüstü düşüşte kinetik enerji artar'], 'Vücut çıtanın üzerinden bölüm bölüm geçerken kütle merkezi çıtanın altında kalabilir; böylece aynı çıta yüksekliği daha düşük bir kütle merkezi yükselişiyle aşılır.'),
  ('Bir sürücünün durma mesafesi, tepki süresinde alınan yol ile fren mesafesinin toplamıdır. Araç süratini iki katına çıkarırsa bu iki parça nasıl değişir?', 'Tepki mesafesi iki, fren mesafesi dört katına çıkar', ['İkisi de iki katına çıkar', 'İkisi de dört katına çıkar', 'Tepki mesafesi değişmez, fren mesafesi iki katına çıkar'], 'Tepki süresinde araç sabit süratle gider (d = v·t), fren mesafesi ise kinetik enerjiyle, yani v² ile orantılıdır.'),
  ('Aşağı doğru sabit hızla inen bir asansör kabinini taşıyan kablonun gerilme kuvvetinin kabin üzerinde yaptığı iş için hangisi doğrudur?', 'Negatiftir', ['Pozitiftir', 'Sıfırdır', 'Kabinin ağırlığına göre pozitif ya da sıfırdır'], 'Kablo kabini yukarı çeker, kabin ise aşağı iner; kuvvet ile yer değiştirme zıt yönlü olduğundan kablonun işi negatiftir.'),
  ('Yay sabiti 500 N/m olan bir yay, denge konumundan 20 cm sıkıştırılıyor. Sıkıştırma süresince yay kuvvetinin, yayı sıkıştıran el üzerinde yaptığı iş kaç joule\'dür?', '−10 J', ['10 J', '−20 J', '−100 J'], 'Yay kuvveti sıkıştırmaya karşı koyar; işi −½kx² = −½·500·0,04 = −10 J\'dür. Elin yaptığı iş ise +10 J\'dür.'),
  ('Eliptik yörüngede dolanan bir gezegen Güneş\'e yaklaşırken Güneş\'in çekim kuvvetinin gezegen üzerinde yaptığı iş için hangisi doğrudur?', 'Pozitiftir ve gezegen hızlanır', ['Sıfırdır, çünkü kuvvet merkezidir', 'Negatiftir ve gezegen yavaşlar', 'Pozitiftir ama gezegenin sürati değişmez'], 'Eliptik yörüngede çekim kuvveti hıza her an dik değildir. Yaklaşırken kuvvetin hareket yönünde bileşeni vardır, iş pozitiftir ve kinetik enerji artar.'),
  ('Bir sarkaç bir taraftan serbest bırakılıyor; ip, en alt noktanın hemen üstündeki bir çiviye takılarak öbür tarafta daha kısa bir sarkaç gibi salınıyor. Sürtünme yoksa top öbür tarafta hangi yüksekliğe çıkar?', 'Bırakıldığı yükseklikle aynı yüksekliğe', ['Bırakıldığından daha yükseğe', 'Bırakıldığından daha alçağa', 'Yalnızca çivinin bulunduğu yüksekliğe kadar'], 'İp gerilmesi iş yapmadığından mekanik enerji korunur; top kinetik enerjisi bitene kadar, yani başlangıç yüksekliğine kadar yükselir. Galileo bu deneyi göstermiştir.'),
  ('Yerden 20 m/s süratle yatayla 60° açı yaparak atılan bir topun, yörüngenin tepe noktasındaki kinetik enerjisi atış anındaki kinetik enerjisinin kaçta kaçıdır? (Hava direnci yok, cos60° = 0,5)', '1/4', ['1/2', '0', '3/4'], 'Tepe noktasında yalnız yatay hız bileşeni kalır: 20·0,5 = 10 m/s. Kinetik enerji süratin karesiyle orantılı olduğundan oran (10/20)² = 1/4.'),
  ('Kütlesi 80 kg olan bir paraşütçü, paraşütü açıldıktan sonra sabit süratle 1000 m alçalıyor. Bu sırada hava direncinin paraşütçü üzerinde yaptığı iş kaç kJ\'dür? (g = 10 m/s²)', '−800 kJ', ['800 kJ', '−8000 kJ', '−80 kJ'], 'Sürat sabit olduğundan net iş sıfırdır; çekimin +mgh = 800 kJ\'lük işini hava direnci −800 kJ ile dengeler.'),
  ('Dört ipli bir palanga ile 1000 N ağırlığındaki bir yük kaldırılırken ipe 300 N kuvvet uygulanması gerekiyor. Palanganın verimi yaklaşık yüzde kaçtır?', '%83', ['%75', '%30', '%100'], 'İdeal palangada kuvvet 1000/4 = 250 N olurdu. Verim = ideal kuvvet / gerçek kuvvet = 250/300 ≈ 0,83.'),
  ('Uzunluğu 5 m, yüksekliği 1 m olan bir rampada 500 N ağırlığındaki bir sandık, rampaya paralel 125 N kuvvetle sabit hızla yukarı itiliyor. Rampanın verimi yüzde kaçtır?', '%80', ['%20', '%25', '%100'], 'Yararlı iş 500·1 = 500 J, harcanan iş 125·5 = 625 J\'dür. Verim 500/625 = %80.'),
  ('İki cisimden oluşan yalıtılmış bir sistemde momentumun korunumu, Newton\'un hangi yasasından doğrudan türetilebilir?', 'Üçüncü yasasından (etki-tepki)', ['Birinci yasasından (eylemsizlik)', 'Evrensel çekim yasasından', 'Soğuma yasasından'], 'Cisimlerin birbirine uyguladığı kuvvetler eşit ve zıttır; bu kuvvetler aynı sürede eşit ve zıt itmeler verir, böylece toplam momentum değişmez.'),
  ('Bir kamyon ile küçük bir otomobil kafa kafaya çarpışıyor. Çarpışma süresince hangi aracın hızındaki değişim daha büyüktür?', 'Otomobilin', ['Kamyonun', 'İkisininki eşittir', 'Hızı başlangıçta büyük olanın'], 'İki araca etkiyen itmeler eşit büyüklüktedir; Δv = I/m olduğundan kütlesi küçük olan otomobilin hız değişimi, dolayısıyla ivmesi çok daha büyüktür.'),
  ('Momentumları eşit büyüklükte olan iki cisim, aynı büyüklükte sabit fren kuvvetleriyle durduruluyor. Durma süreleri için hangisi doğrudur?', 'Süreler eşittir', ['Ağır cismin süresi daha uzundur', 'Hafif cismin süresi daha uzundur', 'Hızlı cismin süresi daha kısadır'], 'Durdurmak için gereken itme momentuma eşittir: F·t = p. Kuvvet ve momentum aynıysa süreler de eşittir.'),
  ('Kinetik enerjileri eşit olan iki cisim, aynı büyüklükte sabit fren kuvvetleriyle durduruluyor. Durana kadar aldıkları yollar için hangisi doğrudur?', 'Yollar eşittir', ['Ağır cismin yolu daha uzundur', 'Hafif cismin yolu daha uzundur', 'Yavaş cismin yolu daha uzundur'], 'Durdurmak için gereken iş kinetik enerjiye eşittir: F·d = E_k. Kuvvet ve enerji aynıysa yollar da eşittir.'),
  ('Raylarda 5 m/s ile giden 4 tonluk üstü açık bir yük vagonuna, bir silodan 1 ton tahıl düşey olarak boşaltılıyor. Sürtünme yoksa vagonun yeni sürati kaç m/s olur?', '4 m/s', ['5 m/s', '1 m/s', '6,25 m/s'], 'Tahılın yatay momentumu yoktur; yatay momentum korunur: 4·5 = 5·v, v = 4 m/s.'),
  ('Sürtünmesiz buz üzerinde duran 50 kg\'lık bir patenci, kendisine 10 m/s ile yatay atılan 2 kg\'lık bir sağlık topunu yakalıyor. Patencinin yakaladıktan sonraki sürati yaklaşık kaç m/s\'dir?', '0,38 m/s', ['0,4 m/s', '10 m/s', '3,8 m/s'], 'Momentum korunumu: 2·10 = 52·v, v = 20/52 ≈ 0,38 m/s.'),
  ('Buz üzerinde duran bir patenci, kendisine atılan bir topu üç farklı biçimde karşılıyor: yakalayıp tutuyor, topa dokunmadan geçmesine izin veriyor ya da yakalayıp aynı süratle geri atıyor. Patencinin kazandığı sürat hangi durumda en büyüktür?', 'Yakalayıp geri attığında', ['Yakalayıp tuttuğunda', 'Topa dokunmadığında', 'Üç durumda da eşittir'], 'Geri atmada topun momentumu tersine döner; patenciye aktarılan momentum, yalnız yakalamaya göre yaklaşık iki katıdır.'),
  ('Aynı mermi, durgun tahta bir bloğa bir kez saplanarak, bir kez de bloğu delip geçerek çarpıyor. Bloğun kazandığı sürat hangi durumda daha büyüktür?', 'Merminin bloğa saplandığı durumda', ['Merminin bloğu delip geçtiği durumda', 'İki durumda eşittir', 'Bloğun kütlesine göre değişir, karşılaştırılamaz'], 'Saplanan mermi bütün momentumunu bloğa aktarır; delip geçen mermi ise momentumunun bir kısmını yanında götürür.'),
  ('Yay sabiti 400 N/m olan bir yay 10 cm sıkıştırılarak 1 kg\'lık bir bloğu fırlatıyor. Blok yaydan ayrıldıktan sonra sürtünme katsayısı 0,25 olan yatay bir zeminde kaç metre gidip durur? (g = 10 m/s²)', '0,8 m', ['2 m', '0,2 m', '8 m'], 'Yaydaki enerji ½·400·0,01 = 2 J\'dür. Bu enerji sürtünmeyle harcanır: 2 = 0,25·1·10·d, d = 0,8 m.'),
  ('Sabit güçle çalışan bir motorun hızlandırdığı bir araç süratlendikçe ivmesi nasıl değişir? (Dirençler ihmal)', 'Azalır', ['Artar', 'Sabit kalır', 'Önce sıfır olur sonra artar'], 'Sabit güçte itici kuvvet F = P/v\'dir; sürat arttıkça kuvvet, dolayısıyla ivme a = P/(mv) azalır.'),
  ('Bir gülle atıcı 7,26 kg\'lık gülleyi 0,3 s süren itiş hareketi sonunda 14 m/s süratle bırakıyor. Atıcının gülleye aktardığı ortalama güç yaklaşık kaç kW\'tır? (Yükseklik değişimi ihmal)', '2,4 kW', ['0,7 kW', '24 kW', '0,34 kW'], 'Güllenin kinetik enerjisi ½·7,26·196 ≈ 711 J\'dür. Ortalama güç 711/0,3 ≈ 2370 W ≈ 2,4 kW.'),
  ('Eski mühendislik hesaplarında kullanılan 1 kilogram-kuvvet metre (kgf·m) yaklaşık kaç joule\'dür?', '9,8 J', ['1 J', '98 J', '0,98 J'], '1 kgf, 1 kg kütlenin standart yer çekimindeki ağırlığıdır (≈ 9,81 N). Bu kuvvetle 1 m\'de yapılan iş ≈ 9,8 J\'dür.'),
  ('Kangurular zıplarken bacaklarındaki uzun tendonlardan yararlanarak enerji tasarrufu yapar. Bu tasarrufun fiziksel dayanağı nedir?', 'İnişte gerilen tendonların enerjiyi depolayıp sıçramada geri vermesi', ['Tendonların vücut kütlesini azaltması', 'Tendonların kaslara ek kimyasal enerji sağlaması', 'Tendonların zıplama sırasında hava direncini tamamen ortadan kaldırması'], 'İnişte kinetik enerjinin önemli bir kısmı tendonlarda yay gibi depolanır ve bir sonraki sıçramada geri kazanılır; kasların yapması gereken iş azalır.'),
  ('Bisiklet ve motosiklet kasklarının içindeki köpük tabakası bir darbede ezildikten sonra kaskın değiştirilmesi önerilir. Bunun nedeni hangisidir?', 'Köpük kalıcı biçim değiştirerek enerji soğurur; ikinci darbede işe yaramaz', ['Köpük ezilince kaskın kütlesi artar', 'Ezilen köpük momentumu ters yöne çevirir', 'Ezilen köpük bir sonraki darbede başa uygulanan itmeyi tamamen sıfırlar ve tehlikelidir'], 'Köpük, darbe enerjisini ezilerek soğurur ve durma süresini uzatır. Bu biçim değişikliği kalıcı olduğundan ikinci darbede aynı korumayı sağlamaz.'),
  ('Otoyollarda bölünme noktalarının önüne yerleştirilen, su ya da kum dolu plastik varil dizilerinin bir araca çarpıldığında sağladığı koruma nasıl açıklanır?', 'Aracın momentumu varillerin kütlesine kademeli aktarılır ve yavaşlama süresi uzar', ['Variller aracı esnek çarpışmayla geri sektirir', 'Variller aracın kütlesini azaltır', 'Variller aracın kinetik enerjisini artırarak yolda kaymasını ve devrilmesini önler'], 'Araç her vari ile çarpıştıkça bir kısım kütleyi hızlandırır; momentum adım adım paylaşılır, yavaşlama süresi uzar ve araca etkiyen ortalama kuvvet azalır.'),
  ('Newton\'un Principia\'sını Fransızcaya çeviren ve kinetik enerjinin mv² ile orantılı olduğu görüşünü savunan 18. yüzyıl Fransız bilim insanı kimdir?', 'Émilie du Châtelet', ['Sophie Germain', 'Marie-Anne Lavoisier', 'Maria Gaetana Agnesi'], 'Émilie du Châtelet\'nin yorumlu Principia çevirisi ölümünden sonra 1759\'da yayımlanmıştır; Leibniz\'in vis viva görüşünü deneysel kanıtlarla desteklemiştir.'),
  ('Simetriler ile korunum yasaları arasındaki derin bağı 1918\'de kanıtladığı teoremle ortaya koyan Alman matematikçi kimdir?', 'Emmy Noether', ['Sofia Kovalevskaya', 'Lise Meitner', 'Hermann Weyl'], 'Noether teoremine göre her sürekli simetri bir korunum yasasına karşılık gelir; örneğin zamanda öteleme simetrisi enerjinin korunumunu verir.'),
  ('CGS sistemindeki enerji birimi ‘erg’ adını hangi anlamdaki Yunanca sözcükten almıştır?', 'İş', ['Güç', 'Kuvvet', 'Hareket'], 'Erg, Yunanca ‘ergon’ (iş) sözcüğünden türetilmiştir. ‘Enerji’ sözcüğü de aynı kökten gelen ‘energeia’dan (etkinlik) türemiştir.'),
  ('Ay\'ın yüzeyinden kaçış hızı yaklaşık kaç km/s\'dir?', '2,4 km/s', ['11,2 km/s', '0,8 km/s', '7,9 km/s'], 'Ay\'ın kütlesi ve yarıçapı küçük olduğundan kaçış hızı yaklaşık 2,38 km/s\'dir. Apollo modüllerinin Ay\'dan kalkışı bu nedenle görece kolay olmuştur.'),
  ('Dairesel yörüngedeki bir uydu, yörünge yarıçapı 4 katı olan başka bir dairesel yörüngeye taşınıyor. Uydunun kinetik enerjisi nasıl değişir?', 'Dörtte birine iner', ['Dört katına çıkar', 'Yarıya iner', 'Değişmez, aynı kalır'], 'Dairesel yörüngede E_k = GMm/(2r)\'dir; yarıçap 4 katına çıkınca kinetik enerji 1/4\'üne iner.'),
  ('Bazı yarış ve şehir otomobillerinde frenleme sırasında hızla döndürülen bir volan kullanılır. Bu düzenin amacı nedir?', 'Fren enerjisini dönme enerjisi olarak saklayıp hızlanmada kullanmak', ['Aracın ağırlık merkezini sürekli yükseltmek', 'Fren balatalarını soğutmak için hava pompalamak', 'Aracın momentumunu tamamen yok ederek virajlarda savrulmayı önlemek'], 'Volanlı kinetik enerji geri kazanım sistemleri, frende boşa gidecek kinetik enerjiyi volanın dönme enerjisine aktarır ve gerektiğinde tekerleklere geri verir.'),
  ('Kütleleri ve yarıçapları eşit olan ince bir halka ile içi dolu bir disk, aynı açısal hızla kendi eksenleri çevresinde dönüyor. Halkanın dönme kinetik enerjisi diskinkinin kaç katıdır? (I_halka = mr², I_disk = ½mr²)', '2 katı', ['Yarısı', 'Eşittir, çünkü ω aynıdır', '4 katı'], 'Aynı ω\'da dönme enerjisi eylemsizlik momentiyle orantılıdır: mr² / (½mr²) = 2.'),
  ('Momentum korunumunu incelemek için yapılan deneylerde arabaların hava rayında (hava yastıklı yüzeyde) hareket ettirilmesinin amacı nedir?', 'Sürtünme gibi dış kuvvetleri en aza indirmek', ['Arabaların kütlelerini azaltmak', 'Çarpışmaları tam esnek hâle getirmek', 'Arabaların hızlarını sabit tutmak için itki sağlamak'], 'Momentum ancak net dış kuvvet sıfırken korunur. Hava yastığı sürtünmeyi neredeyse yok ederek bu koşula yaklaşmayı sağlar.'),
  ('Uzun bir yokuştan sabit süratle inen bir otomobilin frenlerinde açığa çıkan ısının kaynağı esas olarak nedir?', 'Otomobilin kaybettiği çekim potansiyel enerjisi', ['Otomobilin artan kinetik enerjisi', 'Motorun yaktığı yakıtın enerjisi', 'Lastiklerde depolanan ve geri verilen esneklik potansiyel enerjisi'], 'Sürat sabit olduğundan kinetik enerji değişmez; alçalırken kaybedilen çekim potansiyel enerjisi frenlerde sürtünmeyle ısıya dönüşür.'),
  ('Çarpışma problemlerinde, çarpışma anı için momentumun korunduğu kabul edilirken sürtünme ya da çekim gibi dış kuvvetler çoğu zaman ihmal edilir. Bunun gerekçesi nedir?', 'Çarpışma çok kısa sürdüğünden dış kuvvetlerin itmesi küçüktür', ['Dış kuvvetler çarpışma anında tamamen yok olur', 'Dış kuvvetler yalnız enerjiyi etkiler, momentumu ise hiçbir zaman etkilemez', 'Çarpışmada cisimlerin kütlesi sıfıra yaklaşır'], 'Çarpışmadaki iç kuvvetler çok büyük, süre çok kısadır. Sınırlı büyüklükteki dış kuvvetlerin bu kısa sürede verdiği itme, momentumu belirgin biçimde değiştiremez.'),
  ('Sabit hızla giden bir kaykayın üzerindeki genç, düşey olarak yukarı zıplıyor. Sürtünme ve hava direnci yoksa genç nereye düşer?', 'Yeniden kaykayın üzerine', ['Kaykayın gerisine', 'Kaykayın önüne', 'Kaykayın hızına göre kaykayın yanına'], 'Zıplama düşey olduğundan genç, kaykayla aynı yatay hızı korur; havadayken ikisi yatayda birlikte ilerler ve genç kaykaya iner.'),
  ('Bir vinç halatı ağır bir yükü önce hızlandırarak, sonra sabit hızla ve en sonda yavaşlatarak yukarı kaldırıyor. Yük başta ve sonda durgunsa halatın yaptığı toplam iş neye eşittir?', 'Yükün çekim potansiyel enerjisindeki artışa', ['Yükün en büyük kinetik enerjisine', 'Sıfıra, çünkü yük hem başta hem sonda durgundur', 'Potansiyel enerji artışının iki katına'], 'Başta ve sonda kinetik enerji sıfır olduğundan net iş sıfırdır: halatın işi + çekimin işi = 0. Halatın işi mgh\'ye eşittir.'),
  ('Bir araba, sürtünmesiz bir yolda 3 m/s\'den 5 m/s\'ye hızlanırken üzerinde yapılan net iş 32 J\'dür. Arabanın kütlesi kaç kg\'dır?', '4 kg', ['2 kg', '8 kg', '16 kg'], 'W = ½m(v₂² − v₁²) → 32 = ½m(25 − 9) = 8m, m = 4 kg.'),
  ('Kütlesi 2 kg olan bir blok, yatayla 37° açı yapan bir eğik düzlemde 5 m aşağı kayıyor. Kinetik sürtünme katsayısı 0,5 ise sürtünme kuvvetinin yaptığı iş kaç joule\'dür? (g = 10 m/s², cos37° = 0,8)', '−40 J', ['−50 J', '−60 J', '−30 J'], 'Normal kuvvet mg·cos37° = 16 N, sürtünme 0,5·16 = 8 N\'dur. İş W = −8·5 = −40 J.'),
  ('Asansörlerde kabinle ters yönde hareket eden ve kabine halatla bağlı bir karşı ağırlık kullanılır. Bunun enerji açısından yararı nedir?', 'Motor yalnız kabin ile karşı ağırlığın ağırlık farkını kaldırır', ['Karşı ağırlık kabinin kütlesini azaltır', 'Karşı ağırlık kabine sürekli enerji üretir', 'Karşı ağırlık sürtünmeyi tamamen ortadan kaldırarak verimi %100 yapar'], 'Kabin yükselirken karşı ağırlık alçalır ve kaybettiği potansiyel enerji kabinin kazandığına katkı verir; motorun gücü ve harcadığı enerji büyük ölçüde azalır.'),
  ('Bir asansör kabini yolcularla birlikte 1200 kg, karşı ağırlığı 800 kg\'dır. Kabin 2 m/s sabit hızla yükselirken kayıplar ihmal edilirse motorun vermesi gereken güç kaç kW\'tır? (g = 10 m/s²)', '8 kW', ['24 kW', '40 kW', '16 kW'], 'Motor yalnız ağırlık farkını taşır: (1200 − 800)·10 = 4000 N. Güç P = 4000·2 = 8000 W.'),
  ('İki cisimli bir sistem, kütle merkeziyle birlikte hareket eden bir gözlemciye göre inceleniyor. Bu gözlemciye göre sistemin toplam momentumu nedir?', 'Sıfırdır', ['Sistemin toplam kinetik enerjisine eşittir', 'Ağır cismin momentumuna eşittir', 'Her zaman pozitif bir değerdir'], 'Kütle merkezi çerçevesinde kütle merkezinin hızı sıfırdır; toplam momentum M·v_km olduğundan bu çerçevede toplam momentum sıfırdır.'),
  ('Kinetik enerjileri eşit olan bir elektron ile bir proton karşılaştırıldığında momentumları için hangisi doğrudur?', 'Protonun momentumu daha büyüktür', ['Elektronun momentumu daha büyüktür', 'Momentumları eşittir', 'Elektronun momentumu sıfırdır'], 'p = √(2mE_k) olduğundan aynı enerjide kütlesi büyük olan protonun momentumu daha büyüktür (yaklaşık 43 kat).'),
  ('Dönebilen bir taburede durgun oturan bir öğrenci, elinde ekseni düşey olacak biçimde hızla dönen bir bisiklet tekerleği tutuyor. Öğrenci tekerleği ters çevirirse ne olur?', 'Öğrenci tabureyle birlikte dönmeye başlar', ['Öğrenci hareketsiz kalır, tekerlek durur', 'Tekerlek dönmeyi bırakıp öğrenciye enerji verir', 'Tabure ileri doğru kaymaya başlar'], 'Düşey eksen çevresindeki toplam açısal momentum korunur. Tekerleğin açısal momentumu tersine dönünce öğrenci, farkı karşılayacak biçimde ilk yönde dönmeye başlar.'),
  ('Uzay ajansları uyduları tercihen ekvatora yakın üslerden ve doğu yönünde fırlatmayı yeğler. Bunun enerji açısından nedeni nedir?', 'Dünya\'nın dönüşü rokete hazır bir hız kazandırır', ['Ekvatorda yer çekimi sıfırdır', 'Doğuya doğru hava direnci yoktur', 'Ekvatordaki sıcak havada roket yakıtı daha çok enerji verir'], 'Ekvatordaki bir nokta Dünya\'nın dönüşüyle yaklaşık 465 m/s hızla doğuya gider. Doğuya fırlatılan roket bu hızı hazır bulur ve daha az yakıt harcar.'),
  ('Biri alçak, öteki yüksek dairesel yörüngede dolanan özdeş iki uydudan hangisinin toplam mekanik enerjisi daha büyüktür?', 'Yüksek yörüngedeki uydunun', ['Alçak yörüngedeki uydunun', 'İkisininki eşittir', 'Yörünge hızı daha büyük olan uydunun'], 'Toplam enerji E = −GMm/(2r)\'dir; r büyüdükçe enerji daha az negatif, yani daha büyük olur. Bu yüzden yörüngeyi yükseltmek enerji gerektirir.'),
  ('Eşit kütleli iki top birbirine dik doğrultularda eşit süratlerle gelip çarpışıyor ve yapışıyor. Ortak hareketin doğrultusu ilk doğrultularla kaçar derece açı yapar?', '45°', ['90°', '30°', '60°'], 'Momentum bileşenleri eşit olduğundan bileşke momentum iki doğrultunun tam ortasındadır; her biriyle 45° açı yapar.'),
  ('Fren yaparak duran bir otomobilin başlangıçtaki momentumu nereye gider?', 'Sürtünme yoluyla Dünya\'ya aktarılır', ['Isıya dönüşerek yok olur', 'Otomobilin içinde birikir', 'Havaya ses dalgası olarak geçip dağılır'], 'Momentum yok olmaz. Yolun otomobile uyguladığı sürtünme kuvvetinin tepkisi Dünya\'ya etki eder; Dünya\'nın kütlesi çok büyük olduğundan kazandığı hız fark edilmez.'),
  ('Bir otomobil 1 km\'lik düz yolu önce 60 km/h, sonra 120 km/h sabit süratle gidiyor. Hava direnci süratin karesiyle orantılıysa ikinci seferde yalnız hava direncine karşı yapılan iş birincinin kaç katıdır?', '4 katı', ['2 katı', '8 katı', 'Eşittir'], 'Aynı yolda iş W = F·d\'dir; direnç kuvveti v² ile orantılı olduğundan sürat iki katına çıkınca iş 4 katına çıkar. Güç ise 8 katına çıkar.'),
  ('Kütlesi 0,5 kg olan bir top 4 m/s ile sağa giderken bir duvara çarpıp 4 m/s ile sola dönüyor. Topun kinetik enerjisindeki değişim kaç joule\'dür?', '0 J', ['8 J', '4 J', '−8 J'], 'Kinetik enerji yalnız sürate bağlıdır; sürat değişmediğinden enerji değişimi sıfırdır. Momentum ise 4 kg·m/s değişmiştir.'),
  ('İki çelik bilye esnek olarak çarpışırken, birbirlerini en çok sıkıştırdıkları kısa anda toplam kinetik enerji için hangisi doğrudur?', 'Geçici olarak azalır, sonra geri kazanılır', ['Çarpışma boyunca hiç değişmeden sabit kalır', 'Kalıcı olarak ısıya dönüşür', 'Momentumla birlikte sıfıra iner'], 'Esnek çarpışmada bilyeler yay gibi sıkışır; kinetik enerjinin bir bölümü kısa süre esneklik enerjisine dönüşür ve ayrılırken tamamen geri verilir.'),
  ('Bir süs havuzundaki fıskiye saniyede 2 kg suyu 20 m/s hızla püskürtüyor. Pompanın yalnız suya bu hızı kazandırmak için vermesi gereken güç kaç watt\'tır?', '400 W', ['40 W', '800 W', '4000 W'], 'Saniyede kazandırılan kinetik enerji ½·ṁ·v² = ½·2·400 = 400 J\'dür; güç 400 W\'tır.'),
  ('Bir yangın hortumunun ucundan düşey yukarı çıkan su 30 m yükseğe ulaşabiliyor. Hava direnci ihmal edilirse suyun hortumdan çıkış sürati en az kaç m/s\'dir? (g = 10 m/s²)', '24,5 m/s', ['30 m/s', '17,3 m/s', '600 m/s'], '½v² = gh eşitliğinden v = √(2·10·30) = √600 ≈ 24,5 m/s.'),
  ('Bir yay 5 cm uzatıldığında 2 J esneklik enerjisi depoluyor. Yayın sabiti kaç N/m\'dir?', '1600 N/m', ['800 N/m', '80 N/m', '16 000 N/m'], '½kx² = 2 → k = 4/x² = 4/0,0025 = 1600 N/m.'),
  ('İnce cidarlı bir halka, 2,5 m yükseklikteki bir rampadan durgun hâlden kaymadan yuvarlanıyor. Rampanın dibindeki sürati kaç m/s\'dir? (g = 10 m/s², I = mr²)', '5 m/s', ['7,1 m/s', '2,5 m/s', '10 m/s'], 'Halkada kinetik enerji yarı öteleme yarı dönmedir: mgh = mv², v = √(gh) = √25 = 5 m/s.'),
  ('Newton\'un Principia\'da ‘hareket miktarı’ (quantitas motus) adıyla tanımladığı ve kütle ile hızın çarpımı olan nicelik bugün nasıl adlandırılır?', 'Momentum', ['Kinetik enerji', 'İtme', 'Güç'], 'Newton, hareket miktarını hız ile madde miktarının çarpımı olarak tanımlamış ve ikinci yasasını bu niceliğin değişimi üzerinden kurmuştur.'),
  ('Bir sürücü otoyolda süratini 90 km/h\'ten 120 km/h\'e çıkarıyor. Aracın kinetik enerjisi yaklaşık kaç katına çıkar?', '1,78 katına', ['1,33 katına', '2 katına', '4 katına'], 'Oran (120/90)² = (4/3)² = 16/9 ≈ 1,78\'dir. Sürattaki %33\'lük artış enerjiyi %78 artırır.'),
  ('Bir trambolin sporcusu her sıçrayışta biraz daha yükseğe çıkabiliyor. Bu ek enerjinin kaynağı nedir?', 'Sporcunun bacak kaslarıyla zara yaptığı ek iş', ['Trambolin zarının kendiliğinden enerji üretmesi', 'Hava direncinin sporcuyu yukarı itmesi', 'Yer çekiminin her sıçrayışta azalması'], 'Zar enerjiyi yalnız depolayıp geri verir, hatta bir kısmını kaybeder. Sporcu inişte bacaklarını iterek zara ek iş yapar ve mekanik enerjisini artırır.'),
  ('Bir yay-kütle sistemi sürtünmesiz ortamda salınıyor. Sistemin toplam mekanik enerjisini iki katına çıkarmak için genlik kaç katına çıkarılmalıdır?', '√2 katına', ['2 katına', '4 katına', '1/2 katına'], 'Toplam enerji ½kA² ile genliğin karesiyle orantılıdır; enerjinin iki katı için genlik √2 katına çıkarılmalıdır.'),
  ('Aynı süratle giden boş ve dolu iki özdeş kamyon, frenlerinden eşit büyüklükte sabit kuvvetler uygulanarak durduruluyor. Durma mesafeleri için hangisi doğrudur?', 'Dolu kamyonunki daha uzundur', ['Boş kamyonunki daha uzundur', 'İkisininki eşittir', 'Kuvvet eşit olduğundan ikisi de hemen durur'], 'Durdurmak için gereken iş kinetik enerjiye eşittir: F·d = ½mv². Kuvvet ve sürat aynıyken kütlesi büyük olan dolu kamyonun mesafesi daha uzundur.'),
  ('Kalkış anında kütlesi 100 ton olan bir roketin motorları 1,2 MN itki üretiyor. Roketin kalkıştaki ivmesi kaç m/s²\'dir? (g = 10 m/s²)', '2 m/s²', ['12 m/s²', '10 m/s²', '0,2 m/s²'], 'Ağırlık 10⁶ N\'dur. Net kuvvet 1,2·10⁶ − 10⁶ = 2·10⁵ N; a = 2·10⁵/10⁵ = 2 m/s².'),
  ('Sürtünmesiz buz üzerinde aralarında 10 m bulunan 60 kg ve 40 kg kütleli iki patenci, aralarındaki bir ipi çekerek birbirine yaklaşıyor. Buluştukları noktaya 60 kg\'lık patenci kaç metre gitmiştir?', '4 m', ['6 m', '5 m', '2,5 m'], 'Dış kuvvet olmadığından kütle merkezi yerinde kalır; patenciler kütle merkezinde buluşur. Kütle merkezi 60 kg\'lık patenciden 10·40/100 = 4 m uzaktadır.'),
  ('Bir kalkan, kendisine fırlatılan bir topu tamamen durdurduğunda mı yoksa geri sektirdiğinde mi daha büyük itme alır?', 'Topu geri sektirdiğinde', ['Topu durdurduğunda', 'İki durumda eşittir', 'Topun kütlesine göre değişir'], 'Geri sekmede topun momentumu tersine döner ve momentum değişimi, dolayısıyla kalkanın aldığı itme, durdurmaya göre daha büyüktür.'),
  ('Yerde yan yana duran, her biri 2 kg kütleli ve 10 cm kalınlığındaki üç özdeş tuğla üst üste dizilerek bir sütun oluşturulacak. Bunun için yapılması gereken en az iş kaç joule\'dür? (g = 10 m/s²)', '6 J', ['4 J', '2 J', '12 J'], 'Alttaki tuğla yerinde kalır; ikinci tuğla 0,1 m, üçüncüsü 0,2 m yükseltilir: 20·0,1 + 20·0,2 = 6 J.'),
  ('Sürtünmesiz yatay bir düzlemde durgun duran 1 kg ve 4 kg\'lık iki cisme, aynı büyüklükte sabit kuvvetler aynı mesafe boyunca uygulanıyor. Kuvvetler kesildiğinde cisimler için hangisi doğrudur?', 'Kinetik enerjileri eşittir', ['Momentumları eşittir', 'Süratleri eşittir', 'Ağır cismin kinetik enerjisi 4 katıdır'], 'Her iki cisme de F·d kadar eşit iş yapılmıştır; iş-enerji teoremine göre kinetik enerjileri eşittir. Süratleri ve momentumları ise farklıdır.'),
  ('Bir halterci halteri başının üstünden yavaşça indirip yere bırakıyor. İndirme sırasında haltercinin halter üzerinde yaptığı iş için hangisi doğrudur?', 'Negatiftir', ['Pozitiftir', 'Sıfırdır', 'Halterin ağırlığı kadar pozitiftir'], 'Halterci halteri yukarı yönlü bir kuvvetle tutarken halter aşağı iner; kuvvet ile yer değiştirme zıt olduğundan iş negatiftir.'),
  ('Bir apartmanın çatısındaki depoya her gün 10 m³ su, yerden 30 m yükseğe pompalanıyor. Kayıplar ihmal edilirse bu iş için günde en az kaç kWh enerji gerekir? (Su yoğunluğu 1000 kg/m³, g = 10 m/s²)', '0,83 kWh', ['3 kWh', '8,3 kWh', '0,083 kWh'], 'Gereken enerji mgh = 10 000·10·30 = 3·10⁶ J\'dür. 1 kWh = 3,6·10⁶ J olduğundan 3/3,6 ≈ 0,83 kWh.'),
  ('Bir yay-kütle sisteminde yaya bağlı kütle değiştirilip genlik aynı tutulursa sistemin toplam mekanik enerjisi nasıl değişir?', 'Değişmez', ['Kütleyle doğru orantılı artar', 'Kütleyle ters orantılı azalır', 'Kütlenin karesiyle artar'], 'Toplam enerji ½kA²\'dir ve yalnız yay sabiti ile genliğe bağlıdır. Kütle değişince en büyük sürat değişir, enerji değişmez.'),
  ('Yürüme sırasında vücudun kütle merkezi her adımda yükselip alçalır. Biyomekanikte yürümenin enerji açısından ters bir sarkaca benzetilmesinin nedeni nedir?', 'Kinetik ve potansiyel enerjinin birbirine dönüşmesi', ['Bacakların yay gibi enerji depolayıp hiç kaybetmemesi', 'Vücudun dönme enerjisinin sabit kalması', 'Kasların hiç iş yapmaması'], 'Bacak üzerinden geçerken kütle merkezi yükselir ve yavaşlar (kinetik → potansiyel), ardından alçalırken hızlanır; bu değiş tokuş kasların yapması gereken işi azaltır.'),
  ('20 m/s ile giden bir otobüste 0,5 kg\'lık bir top, otobüse göre ileri doğru 2 m/s ile yuvarlanıyor. Topun yere göre kinetik enerjisi kaç joule\'dür?', '121 J', ['1 J', '100 J', '242 J'], 'Yere göre hız 20 + 2 = 22 m/s\'dir: E_k = ½·0,5·22² = 121 J. Otobüse göre ise yalnız 1 J\'dür.'),
  ('Bir top her yere çarpışında mekanik enerjisinin %20\'sini kaybediyor. 5 m yükseklikten bırakılan top üçüncü kez yerden sektikten sonra en fazla kaç metre yükselir? (Hava direnci yok)', '2,56 m', ['2 m', '2,048 m', '0,04 m'], 'Her sekmeden sonra enerji, dolayısıyla çıkılan yükseklik 0,8 katına iner: 5·0,8³ = 5·0,512 = 2,56 m.'),
  ('Bir öğrenci ‘Otoyolda sabit hızla giden bir otomobile etki eden net kuvvet sıfır olduğuna göre motor hiç iş yapmıyordur.’ diyor. Bu yargı için hangisi doğrudur?', 'Yanlıştır; motorun işini dirençlerin işi dengeler', ['Doğrudur; net kuvvet sıfırsa hiçbir kuvvet iş yapmaz', 'Doğrudur; sabit hızda yakıt harcanmaz', 'Yanlıştır; çünkü net kuvvet aslında sıfırdan büyüktür'], 'Net kuvvetin sıfır olması net işin sıfır olduğunu gösterir. Motorun itici kuvveti pozitif iş yaparken hava direnci ve sürtünme eşit büyüklükte negatif iş yapar.'),
  ('Bir öğrenci ‘Ağır bir taşın potansiyel enerjisi daha büyük olduğu için, aynı yükseklikten bırakılınca hafif taştan daha hızlı yere ulaşır.’ diyor. Hava direnci yoksa bu yargıdaki hata nedir?', 'Kütlesi de büyük olduğundan sürati aynıdır', ['Ağır taşın potansiyel enerjisi aslında daha küçüktür', 'Hafif taş daha hızlı düşer', 'Potansiyel enerji kütleye bağlı değildir'], 'mgh = ½mv² eşitliğinde kütle her iki tarafta bulunur ve sadeleşir; bu yüzden düşme sürati kütleye bağlı değildir.'),
  ('Kurulu gücü 2 MW olan bir rüzgâr türbini, rüzgârın değişkenliği nedeniyle bir yıl boyunca ortalama olarak kurulu gücünün %30\'u kadar güç üretiyor. Türbinin yıllık üretimi yaklaşık kaç MWh\'tir? (1 yıl ≈ 8760 saat)', '5256 MWh', ['17 520 MWh', '600 MWh', '2628 MWh'], 'Ortalama güç 0,6 MW\'tır. Yıllık enerji 0,6 MW · 8760 h = 5256 MWh\'tir.'),
  ('Saatte 1 kilokalorilik sürekli bir ısı üretimi yaklaşık kaç watt\'lık güce karşılık gelir? (1 kcal ≈ 4186 J)', '1,16 W', ['4186 W', '0,0116 W', '69,8 W'], 'Güç = 4186 J / 3600 s ≈ 1,16 W.'),
  ('Kartal ve akbaba gibi büyük kuşların yükselen sıcak hava akımlarında kanat çırpmadan uzun süre süzülebilmesinin enerji açısından açıklaması nedir?', 'Sıcak hava akımıyla yükselerek kazandıkları potansiyel enerjiyi harcarlar', ['Kanat çırpmadıklarında kütleleri azalır', 'Havada yer çekimi etkisini yitirir', 'Süzülme sırasında hava direnci olmadığından hiç enerji kaybetmezler'], 'Kuş, termal akımlarda havayla birlikte yükselerek çekim potansiyel enerjisi kazanır; sonra süzülerek bu enerjiyi hava direncine harcar ve kas enerjisinden tasarruf eder.'),
  ('Uzay istasyonunda kütleler terazi ile ölçülemez. Kütlesi bilinmeyen bir cisim ile 2 kg\'lık bir cisim aralarındaki sıkıştırılmış bir yayla itişiyor; 2 kg\'lık cisim 3 m/s, diğeri 1 m/s ile ters yönlere ayrılıyor. Bilinmeyen kütle kaç kg\'dır?', '6 kg', ['2/3 kg', '1,5 kg', '3 kg'], 'Başta toplam momentum sıfırdır: 2·3 = m·1, m = 6 kg. Bu yöntem eylemsizlik kütlesini doğrudan ölçer.'),
  ('Verimi %90 olan bir elektrik motoru şebekeden 1 kWh enerji çekerek yük kaldırıyor. Bu enerjiyle en fazla kaç ton yük 10 m yükseltilebilir? (g = 10 m/s²)', '32,4 ton', ['36 ton', '3,24 ton', '0,324 ton'], 'Yararlı enerji 0,9·3,6·10⁶ = 3,24·10⁶ J\'dür. m = E/(gh) = 3,24·10⁶/100 = 32 400 kg = 32,4 ton.'),
  ('Kütlesi değişmeyen bir cismin kinetik enerjisi iki katına çıkarsa momentumunun büyüklüğü nasıl değişir?', '√2 katına çıkar', ['2 katına çıkar', '4 katına çıkar', 'Değişmez, aynı kalır'], 'p = √(2mE_k) olduğundan enerji 2 katına çıkınca momentum √2 ≈ 1,41 katına çıkar.'),
  ('Bir bisikletin tekerleğine dokunan dinamo çalıştırılıp fener yakıldığında pedal çevirmenin biraz zorlaştığı hissedilir. Bunun nedeni nedir?', 'Fenerin enerjisi bisikletçinin işinden gelir', ['Dinamonun bisikletin kütlesini artırması', 'Fenerin ışığının bisikleti geri itmesi', 'Dinamonun sürtünerek tekerleğin yarıçapını küçültmesi'], 'Enerjinin korunumu gereği dinamonun ürettiği elektrik enerjisi, tekerleği döndürmek için yapılan ek mekanik işten gelir; bu da pedala ek direnç olarak yansır.'),
  ('Bir gemiden atılan bir çapa, deniz dibine çarpana kadar suyun içinde sabit süratle iniyor. Bu iniş sırasında çapanın mekanik enerjisi için hangisi doğrudur?', 'Azalır; enerji suyun direnciyle ısıya döner', ['Sabit kalır; sürat değişmemektedir', 'Artar; çapa hızlanmaktadır', 'Sabit kalır; çünkü suyun kaldırma kuvveti hiç iş yapmaz'], 'Sürat sabit olduğundan kinetik enerji değişmez, ama çapa alçaldıkça potansiyel enerjisi azalır; bu enerji suyun direnci ile ısıya ve suyun hareketine dönüşür.'),
  ('İki atom arasındaki bağın potansiyel enerjisi atomlar arası uzaklığa göre bir çukur oluşturur. Molekülün denge bağ uzunluğu bu eğrinin hangi noktasına karşılık gelir?', 'Potansiyel enerjinin en küçük olduğu noktaya', ['Potansiyel enerjinin sıfır olduğu noktaya', 'Potansiyel enerjinin en büyük olduğu noktaya', 'Eğrinin eğiminin en büyük olduğu, en dik noktasına'], 'Kuvvet F = −dU/dr\'dir; en düşük potansiyel enerjide kuvvet sıfırdır ve atomlar küçük sapmalarda bu konuma geri çekilir, yani kararlı dengedir.'),
  ('1 kg\'lık bir cismi Dünya yüzeyinden sonsuza (kütleçekimin etkisinin bittiği uzaklığa) taşımak için gereken en az enerji yaklaşık kaç joule\'dür? (Dünya yarıçapı 6400 km, yüzeyde g = 10 m/s²)', '6,4 × 10⁷ J', ['6,4 × 10⁴ J', '3,2 × 10⁷ J', '1,2 × 10⁸ J'], 'Gereken enerji GMm/R = mgR = 1·10·6,4·10⁶ = 6,4 × 10⁷ J\'dür.'),
  ('İp atlayan 50 kg\'lık bir çocuk her sıçrayışta kütle merkezini 5 cm yükseltiyor. Çocuk 1 dakikada 120 kez sıçrarsa yalnız yükselmeler için ortalama mekanik gücü kaç watt\'tır? (g = 10 m/s²)', '50 W', ['25 W', '3000 W', '500 W'], 'Her sıçrayış 50·10·0,05 = 25 J\'dür. Dakikada 120·25 = 3000 J; ortalama güç 3000/60 = 50 W.'),
  ('Yer çekiminin Dünya\'dakinin altıda biri olduğu Ay\'da, bir astronot bir taşı Dünya\'da atacağı süratle düşey yukarı atıyor. Hava direnci yoksa taş Dünya\'dakine göre kaç kat yükseğe çıkar?', '6 kat', ['√6 kat', '36 kat', 'Aynı yüksekliğe'], 'Çıkış yüksekliği h = v²/(2g)\'dir; aynı ilk süratte g altıda birine inince yükseklik 6 katına çıkar.'),
  ('1 beygir gücü-saat (hp·h) yaklaşık kaç kilowatt-saattir? (1 hp ≈ 746 W)', '0,746 kWh', ['0,0746 kWh', '1,34 kWh', '2,68 kWh'], '1 hp·h = 746 W · 1 h = 746 Wh = 0,746 kWh.'),
  ('Kütlesi 0,5 kg olan bir top 20 m/s ile düşey yukarı atılıyor; çıkış boyunca hava direnci top üzerinde toplam −20 J iş yapıyor. Top en fazla kaç metre yükselir? (g = 10 m/s²)', '16 m', ['20 m', '24 m', '12,8 m'], 'Başlangıç kinetik enerjisi 100 J\'dür. Tepede potansiyel enerji 100 − 20 = 80 J olur: h = 80/(0,5·10) = 16 m.'),
  ('Havada hareket eden bir top mermisi iç patlamayla parçalara ayrılıyor. Kütle merkezinin hareketine ait kinetik enerji (½M·v_km²) patlama anında nasıl değişir?', 'Değişmez', ['Artar', 'Azalır', 'Sıfıra iner'], 'Patlama kuvvetleri iç kuvvetlerdir; toplam momentum ve dolayısıyla kütle merkezinin hızı değişmez. Patlamanın açığa çıkardığı enerji parçaların kütle merkezine göre hareketine gider.'),
  ('Kütlesi 1500 kg olan bir otomobil 20 m/s ile giderken sürücü gazı bırakıyor ve araç yalnız sabit 500 N\'luk dirençle yavaşlıyor. Araç 10 m/s\'ye düşene kadar kaç metre yol alır?', '450 m', ['300 m', '600 m', '4500 m'], 'Kinetik enerji kaybı ½·1500·(400 − 100) = 225 000 J\'dür. d = 225 000/500 = 450 m.'),
  ('Kütlesi 2 kg olan bir cisim 10 m/s ile giderken hareket yönüne zıt sabit bir kuvvetle 5 s\'de durduruluyor. Kuvvetin büyüklüğü ve yaptığı iş sırasıyla nedir?', '4 N ve −100 J', ['4 N ve +100 J', '20 N ve −100 J', '4 N ve −20 J'], 'İtme-momentum: F·5 = 20 → F = 4 N. İş-enerji: W = 0 − ½·2·100 = −100 J.'),
  ('Üç cisim düşünülsün: A (2 kg, 3 m/s), B (1 kg, 5 m/s), C (4 kg, 2 m/s). Bu cisimlerin kinetik enerjilerinin küçükten büyüğe sıralaması hangisidir?', 'C, A, B', ['A, B, C', 'B, A, C', 'C, B, A'], 'E_A = ½·2·9 = 9 J, E_B = ½·1·25 = 12,5 J, E_C = ½·4·4 = 8 J. Sıralama C < A < B\'dir.'),
  ('Bir kızak, yatayla 37° açı yapan bir iple 100 N kuvvetle çekilerek sabit 2 m/s süratle ilerletiliyor. İp kuvvetinin gücü kaç watt\'tır? (cos37° = 0,8)', '160 W', ['200 W', '120 W', '1600 W'], 'Anlık güç P = F·v·cosθ = 100·2·0,8 = 160 W.'),
  ('Kütlesi 2 kg olan bir cisim durgun hâlden serbest düşüyor. Düşmeye başladıktan 3 s sonra yer çekimi kuvvetinin cisim üzerindeki anlık gücü kaç watt\'tır? (g = 10 m/s², hava direnci yok)', '600 W', ['60 W', '300 W', '6000 W'], '3 s sonra sürat 30 m/s\'dir. Çekimin anlık gücü P = mg·v = 20·30 = 600 W.'),
  ('Eğik atılan bir topun yörüngesinin tepe noktasında yer çekimi kuvvetinin top üzerindeki anlık gücü nedir? (Hava direnci yok)', 'Sıfırdır', ['En büyük değerindedir', 'mg·v₀ kadardır', 'Negatif ve en büyük değerdedir'], 'Tepe noktasında hız yataydır, çekim kuvveti düşeydir; aralarındaki açı 90° olduğundan anlık güç P = F·v·cos90° = 0\'dır.'),
  ('Günlük dilde ‘enerji tüketildi’ denir. Enerjinin korunumu açısından bu ifadenin fiziksel anlamı nedir?', 'Kullanışlı biçimden çoğunlukla ısıya dönüştü', ['Enerji yok oldu ve evrendeki toplam enerji azaldı', 'Enerji kütleye dönüşüp cisimlerde birikti', 'Enerji kullanıldıkça kendiliğinden yeniden oluştu'], 'Enerji yok olmaz; ‘tüketim’, yakıt ya da elektrik gibi yoğun ve kullanışlı enerjinin çevreye dağılan ısıya dönüşmesidir.'),
  ('Aynı dairesel yörüngede dolanan, kütleleri farklı iki uydu karşılaştırılıyor. Hangisi doğrudur?', 'Süratleri eşit, ağırın enerjisi büyüktür', ['Ağır uydu daha hızlı dolanır', 'Hafif uydunun kinetik enerjisi daha büyüktür', 'Süratleri ve enerjileri eşittir'], 'Yörünge sürati √(GM/r) uydunun kütlesine bağlı değildir; kinetik enerji ise ½mv² ile kütleyle orantılıdır.'),
  ('Aynı açıdan bırakılan iki sarkaçtan birinin ipi diğerinin iki katı uzunluktadır. Uzun sarkacın topunun en alt noktadaki sürati kısa olanınkinin kaç katıdır? (Sürtünme yok)', '√2 katı', ['2 katı', '4 katı', 'Değişmez, eşittir'], 'Düşülen yükseklik L(1 − cosθ) ile ipin uzunluğuyla orantılıdır; sürat √(2gh) olduğundan √2 katına çıkar.'),
  ('Fazla elektriği depolamak için 1 tonluk bir beton blok bir kuleye 100 m yükseltiliyor. Depolanan çekim potansiyel enerjisi yaklaşık kaç kWh\'tir? (g = 10 m/s²)', '0,28 kWh', ['100 kWh', '2,8 kWh', '277,8 kWh'], 'E = mgh = 1000·10·100 = 10⁶ J\'dür. 10⁶/3,6·10⁶ ≈ 0,28 kWh. Bu, kütleçekimli depolamanın büyük kütle ve yükseklik gerektirdiğini gösterir.'),
  ('Bir öğrenci kâğıttan yaptığı bir rampada bilyeleri yuvarlıyor ve bir bilyeyi bir kez de buz kalıbını kaydırıyor (sürtünme ihmal). Aynı yükseklikten bırakılan bu iki cisimden hangisinin rampanın sonundaki öteleme sürati daha büyüktür?', 'Buz kalıbının', ['Bilyenin', 'İkisinin aynı', 'Kütlesi küçük olanın'], 'Buz kalıbı dönmediğinden bütün potansiyel enerji öteleme kinetik enerjisine gider; bilyenin enerjisinin bir kısmı dönmeye harcanır.'),
  ('Sürtünmesiz raylar üzerindeki bir topun içinden bir gülle yatay olarak ateşleniyor. Atıştan sonra top ile güllenin oluşturduğu sistemin kütle merkezi yatay doğrultuda nasıl hareket eder?', 'Yatayda yerinde kalır', ['Gülleyle aynı yönde ilerler', 'Topla aynı yönde geri gider', 'Gülle ile aynı süratle ilerler'], 'Yatay doğrultuda dış kuvvet yoktur; başlangıçta durgun olan sistemin kütle merkezi yatayda hareketsiz kalır. Gülle ileri, top geri giderken ağırlıklı ortalamaları değişmez.'),
  ('Kütlesi yaklaşık 6 × 10²⁴ kg olan Dünya, Güneş çevresinde yaklaşık 3 × 10⁴ m/s ile dolanır. Dünya\'nın yörünge kinetik enerjisi yaklaşık kaç joule\'dür?', '2,7 × 10³³ J', ['5,4 × 10³³ J', '1,8 × 10²⁹ J', '2,7 × 10²⁸ J'], 'E_k = ½·6·10²⁴·(3·10⁴)² = ½·6·10²⁴·9·10⁸ = 2,7 × 10³³ J.'),
  ('Yukarı çıkan bir yürüyen merdivende basamağın üzerinde kıpırdamadan duran bir yolcuya basamağın uyguladığı kuvvetin yaptığı iş için hangisi doğrudur?', 'Pozitiftir, çünkü yolcu yükselmektedir', ['Sıfırdır, çünkü yolcu basamağa göre durgundur', 'Negatiftir, çünkü kuvvet çekime zıttır', 'Sıfırdır, çünkü yolcu yürümemektedir'], 'Yere göre yolcu yukarı yer değiştirir ve basamağın kuvveti yukarı yönlüdür; iş pozitiftir ve yolcunun potansiyel enerjisi artar.'),
  ('Yatay bir konveyör bandı üzerinde bant ile birlikte sabit hızla taşınan bir kutuya bandın yaptığı iş nedir? (Hava direnci yok)', 'Sıfırdır', ['Pozitiftir ve kutunun kinetik enerjisini artırır', 'Negatiftir ve kutuyu yavaşlatır', 'Kutunun ağırlığı ile taşınan yolun çarpımıdır'], 'Kutu sabit hızla gittiğinden yatayda net kuvvet ve dolayısıyla sürtünme kuvveti sıfırdır; düşey normal kuvvet de harekete diktir. Bant kutuya iş yapmaz.'),
  ('Durgun 1 kg ve 4 kg\'lık iki cisme eşit büyüklükte itmeler veriliyor. Cisimler için hangisi doğrudur?', 'Momentumları eşit; hafifin enerjisi 4 katıdır', ['Kinetik enerjileri eşittir; ağır cismin momentumu 4 katıdır', 'Süratleri eşittir', 'Momentumları eşittir; kinetik enerjileri de eşittir'], 'Eşit itme eşit momentum kazandırır. E_k = p²/(2m) olduğundan aynı momentumda enerji kütleyle ters orantılıdır: 4 kat.'),
  ('Bir yay esneklik sınırının ötesine kadar gerilip bırakılıyor. Gerilirken yapılan işin tamamının geri alınamamasının nedeni nedir?', 'İşin bir kısmı ısıya dönüşür', ['Yayın kütlesi gerilince azalır', 'Yay kuvveti gerilme boyunca sıfırdır', 'Gerilen yay çekim potansiyel enerjisi kazanır'], 'Esneklik sınırı aşılınca malzemenin iç yapısı kalıcı olarak değişir; bu sırada harcanan enerji iç enerjiye dönüşür ve yay geri dönerken verilemez.'),
  ('Uzun bir otoyol yolculuğundan sonra araç lastiklerinin ısındığı görülür. Bunun başlıca nedeni nedir?', 'Esneyen lastiğin enerjisinin ısıya dönüşmesi', ['Lastiklerin içindeki havanın kimyasal tepkimeye girmesi', 'Güneş ışığının yalnız lastikleri ısıtması', 'Lastiklerin kütlesinin yolculukta artması'], 'Lastik yola değdiği bölgede sürekli ezilip açılır; bu biçim değişiminde harcanan enerjinin tamamı geri verilmez ve yuvarlanma direnci olarak ısıya dönüşür.'),
  ('Malzemelerin darbe dayanımını ölçen sarkaçlı darbe deneyinde (Charpy deneyi) ağır bir sarkaç numuneyi kırıp karşı tarafa geçer. Numunenin soğurduğu enerji nasıl belirlenir?', 'Bırakılma ve çıkış yükseklikleri farkından', ['Sarkacın kütlesinin numunenin kütlesine oranından', 'Numunenin kırılma süresinden', 'Sarkacın ipindeki gerilmenin en büyük değerinden'], 'Sarkacın kaybettiği potansiyel enerji, yani mg(h₁ − h₂), numuneyi kırmak için harcanan enerjiye eşittir.'),
  ('Uzun ve dik bir yokuştan inen ağır yüklü kamyonların sürücülerine düşük vitese geçmeleri önerilir. Bunun enerji açısından amacı nedir?', 'Frenlerin aşırı ısınmasını önlemek', ['Kamyonun kütlesini azaltmak', 'Yokuşun eğimini azaltmak', 'Kamyonun potansiyel enerjisini artırmak'], 'İnişte kaybedilen potansiyel enerjinin tamamı frenlerde ısıya dönüşürse frenler aşırı ısınıp etkisini yitirebilir. Düşük vitesteki motor freni bu enerjinin bir kısmını motorun iç sürtünmelerine aktarır.'),
  ('Salıncaktaki bir çocuk, kimse itmediği hâlde en alt noktada ayağa kalkıp uç noktalarda çömelerek salınımını giderek büyütebiliyor. Salınıma eklenen enerjinin kaynağı nedir?', 'Çocuğun kaslarıyla yaptığı iş', ['Yer çekiminin her salınımda artması', 'Salıncak zincirlerindeki esneklik enerjisi', 'Havanın çocuğu itmesi'], 'Ayağa kalkan çocuk kütle merkezini kaslarıyla yükseltir; bu iş her salınımda mekanik enerjiye eklenir ve genlik büyür.'),
  ('Yük taşımacılığında demiryolunun karayoluna göre ton-kilometre başına daha az enerji harcamasının başlıca mekanik nedeni nedir?', 'Tekerlek-ray yuvarlanma direncinin çok küçük olması', ['Trenlerin raylar üzerinde hiç hava direnciyle karşılaşmaması', 'Trenlerin kütlesinin kamyonlardan küçük olması', 'Raylarda yer çekiminin etkisiz olması'], 'Sert çelik tekerlek ile ray çok az esner; lastik tekerleklere göre yuvarlanma direnci birkaç kat küçük olduğundan aynı yükü taşımak için daha az iş gerekir.'),
  ('Aynı rüzgâr hızında havanın yoğunluğu 1,1 katına çıkarsa bir rüzgâr türbininin rüzgârdan alabileceği güç nasıl değişir?', '%10 artar', ['%21 artar', '%33 artar', 'Değişmez, çünkü hız aynıdır'], 'Rüzgâr gücü ½ρAv³ ile hava yoğunluğuyla doğru orantılıdır; yoğunluktaki %10\'luk artış gücü de %10 artırır.'),
  ('Momentumun korunumu ile enerjinin korunumu arasındaki farkı en iyi açıklayan ifade hangisidir?', 'Momentumun her bileşeni ayrı ayrı korunur', ['Momentum yalnız esnek çarpışmalarda, enerji ise hiçbir zaman korunmaz', 'İkisi de skalerdir ve aynı koşulda korunur', 'Enerji vektöreldir; momentum skalerdir'], 'Dış kuvvet yoksa momentumun x, y ve z bileşenleri ayrı ayrı korunur. Enerji ise tek bir sayıdır ve biçimden biçime dönüşebilir.'),
  ('Kütlesi 1500 kg olan bir otomobil 8 s içinde durgun hâlden 20 m/s\'ye çıkarken bu sürede 5 m yükselen bir yokuşu tırmanıyor. Kayıplar ihmal edilirse motorun ortalama gücü yaklaşık kaç kW\'tır? (g = 10 m/s²)', '47 kW', ['38 kW', '375 kW', '75 kW'], 'Kinetik enerji artışı ½·1500·400 = 300 kJ, potansiyel enerji artışı 1500·10·5 = 75 kJ\'dür. Toplam 375 kJ, ortalama güç 375/8 ≈ 47 kW.'),
  ('Bir otomobil 15 m/s süratle sert bir engele çarpıyor ve ön bölümü 0,5 m buruşarak duruyor. Yavaşlama düzgün kabul edilirse yolcu bölmesinin ortalama ivmesinin büyüklüğü yaklaşık kaç m/s²\'dir?', '225 m/s²', ['22,5 m/s²', '450 m/s²', '112 m/s²'], 'Kinetik enerji buruşma mesafesinde sıfırlanır: v² = 2ad → a = 225/(2·0,5) = 225 m/s², yani yaklaşık 22 g.'),
  ('Kütlesi 1 kg olan bir cisim için iki durum karşılaştırılıyor: 100 m yükseğe kaldırılmış hâlde durgun olması ve yerde 100 m/s ile hareket etmesi. Hangi durumda depolanan mekanik enerji daha fazladır? (g = 10 m/s²)', '100 m/s ile hareket ettiği durumda', ['100 m yükseğe kaldırıldığı durumda', 'İki durumda eşittir', 'Kütle küçük olduğundan karşılaştırılamaz'], 'Yükseklikte enerji mgh = 1000 J, harekette ½mv² = 5000 J\'dür; hareket enerjisi 5 kat büyüktür.'),
  ('Pelton tipi su türbinlerinde jet hâlindeki su, çarkın kepçelerine çarpınca neredeyse geri döndürülür. Bu tasarımın amacı nedir?', 'Momentum değişimini en büyük yapmak', ['Suyun kütlesini artırmak', 'Suyun sıcaklığını yükseltmek', 'Kepçelerin dönme yönünü sürekli değiştirmek'], 'Su geri döndürülünce momentum değişimi yalnız durdurmaya göre yaklaşık iki katına çıkar ve suyun kinetik enerjisinin büyük kısmı çarka aktarılır.'),
  ('Spor salonunda kondisyon bisikleti çeviren bir kişi 30 dakika boyunca ortalama 200 W mekanik güç veriyor. Bu sürede yaptığı mekanik iş yaklaşık kaç kilokaloridir? (1 kcal ≈ 4186 J)', '86 kcal', ['6 kcal', '360 kcal', '1435 kcal'], 'İş 200·1800 = 360 000 J\'dür; 360 000/4186 ≈ 86 kcal. Kas verimi düşük olduğundan vücudun harcadığı enerji bunun birkaç katıdır.'),
  ('Doğuya giden 1000 kg\'lık bir otomobil, kuzeye giden 1500 kg\'lık bir otomobille kavşakta çarpışıp kenetleniyor ve araçlar tam kuzeydoğu yönünde (45°) kayıyor. Çarpışmadan önceki süratlerin oranı (doğuya gidenin / kuzeye gidenin) kaçtır?', '1,5', ['1', '0,67', '2,25'], '45°\'lik ortak yön, iki momentum bileşeninin eşit olduğunu gösterir: 1000·v₁ = 1500·v₂, v₁/v₂ = 1,5.'),
  ('Bir yay 4 N\'luk kuvvetle 2 cm uzuyor. Bu yayı doğal boyundan 6 cm uzatmak için yapılması gereken iş kaç joule\'dür?', '0,36 J', ['0,12 J', '0,24 J', '0,036 J'], 'Yay sabiti k = 4/0,02 = 200 N/m\'dir. W = ½kx² = ½·200·0,0036 = 0,36 J.'),
  ('Balistik sarkaçta mermi bloğa saplandıktan sonra blok yükselirken blok-mermi sisteminin momentumu ve mekanik enerjisi için hangisi doğrudur?', 'Mekanik enerji korunur, momentum korunmaz', ['Momentum korunur, mekanik enerji korunmaz', 'İkisi de korunur', 'İkisi de korunmaz; çünkü ip kuvvet uygular'], 'Yükselirken çekim ve ip gerilmesi dış kuvvet olarak momentumu değiştirir; ip iş yapmadığı ve sürtünme olmadığı için mekanik enerji korunur.'),
  ('Dış kuvvetin etki etmediği herhangi bir çarpışmada, çarpışmanın türü ne olursa olsun her zaman korunan nicelikler hangileridir?', 'Toplam momentum ve toplam enerji', ['Toplam momentum ve toplam kinetik enerji', 'Yalnız toplam kinetik enerji', 'Her cismin ayrı ayrı momentumu'], 'Kinetik enerji yalnız esnek çarpışmalarda korunur; ancak ısı, ses ve biçim değişimi enerjisi de sayılırsa toplam enerji ve toplam momentum her zaman korunur.'),
  ('Bir sistemin parçaları arasındaki iç kuvvetler sistemin toplam kinetik enerjisini değiştirebilir mi?', 'Evet; örneğin patlamada artırır', ['Hayır; iç kuvvetler hiçbir zaman iş yapmaz', 'Hayır; çünkü toplam momentum korunur', 'Evet; ama yalnız sistemin kütlesini değiştirerek'], 'İç kuvvetler toplam momentumu değiştiremez, ama iş yapabilirler: patlamada kimyasal enerjiyi kinetik enerjiye, esnek olmayan çarpışmada kinetik enerjiyi ısıya çevirirler.'),
  ('Kütleleri ve yarıçapları eşit bir halka ile içi dolu bir disk, aynı eğik düzlemin tepesinden kaymadan yuvarlanıyor. Düzlemin dibine ulaştıklarında toplam kinetik enerjileri için hangisi doğrudur?', 'Eşittir', ['Halkanınki daha büyüktür', 'Diskinki daha büyüktür', 'Halkanınki sıfırdır'], 'Her ikisi de aynı mgh kadar potansiyel enerji kaybeder; toplam kinetik enerjileri eşittir. Yalnız bu enerjinin öteleme ve dönme arasındaki paylaşımı farklıdır.'),
  ('Bir hortum (tornado) bulutunun dönen hava kütlesi merkeze doğru daraldıkça rüzgâr hızının çok büyük değerlere çıkması hangi ilkeyle açıklanır?', 'Açısal momentumun korunumu', ['Enerjinin yok olması', 'Momentumun sıfırlanması', 'Havanın kütlesinin korunmaması ve artması'], 'Dönen hava eksene yaklaştıkça eylemsizlik momenti azalır; açısal momentum korunduğundan dönme hızı artar.'),
];
